-- Native source, reconciliation and settlement overlay. No legacy agreement is inferred paid/unpaid.
INSERT INTO sys_perm_resource(resource_code,label,temporal_basis)VALUES('outsource_finance','外包应付与资金办理','CURRENT'),('outsource_private','外包受控联系人与收款资料','CURRENT')ON CONFLICT DO NOTHING;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT r.id,p.resource_code,true,true FROM sys_role r CROSS JOIN sys_perm_resource p WHERE r.code IN('admin','ty_group_hr_director','ty_demo_payroll')AND p.resource_code IN('outsource_finance','outsource_private')ON CONFLICT DO NOTHING;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT r.id,'outsource_private',true,true FROM sys_role r WHERE r.code='ty_outsource_hr'ON CONFLICT DO NOTHING;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT r.id,'outsource_finance',true,false FROM sys_role r WHERE r.code='boss'ON CONFLICT DO NOTHING;

CREATE TABLE ty_wf_vendor_profile(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,supplier_id bigint NOT NULL REFERENCES ty_outsource_supplier(id),group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 version integer NOT NULL CHECK(version>0),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','rejected')),revision integer NOT NULL DEFAULT 1,
 qualification_kind text NOT NULL CHECK(qualification_kind IN('service_provider','dispatch_cn','employment_agency_hk','not_applicable_reviewed')),qualification_valid_from date NOT NULL,qualification_valid_to date NOT NULL,
 qualification_ref text NOT NULL,bank_last4 text CHECK(bank_last4 IS NULL OR bank_last4~'^[0-9]{4}$'),private_cipher text NOT NULL,private_iv text NOT NULL,private_tag text NOT NULL,source_hash text NOT NULL,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),approved_at timestamptz,review_ref text,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(supplier_id,version),CHECK(qualification_valid_to>qualification_valid_from),CHECK(status<>'approved'OR(approved_by IS NOT NULL AND approved_at IS NOT NULL AND length(btrim(review_ref))>=4))
);
CREATE TABLE ty_wf_price(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),contract_id bigint NOT NULL REFERENCES ty_outsource_contract(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 code text NOT NULL,version integer NOT NULL CHECK(version>0),component text NOT NULL CHECK(component IN('base','premium','fixed_fee','minimum_topup')),unit text NOT NULL CHECK(unit IN('hour','shift','day','person_month','result','period')),
 currency text NOT NULL CHECK(currency IN('CNY','HKD')),unit_price numeric(24,6)NOT NULL CHECK(unit_price>=0),minimum_target numeric(24,2),valid_from date NOT NULL,valid_to date NOT NULL,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','rejected')),revision integer NOT NULL DEFAULT 1,rounding text NOT NULL CHECK(rounding IN('line_half_up_2','aggregate_half_up_2')),
 evidence_ref text NOT NULL,source_hash text NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),approved_at timestamptz,review_ref text,
 UNIQUE(contract_id,company_id,code,version),CHECK(valid_to>valid_from),CHECK((component='minimum_topup')=(minimum_target IS NOT NULL)),CHECK(minimum_target IS NULL OR minimum_target>=0),CHECK(status<>'approved'OR(approved_by IS NOT NULL AND approved_at IS NOT NULL))
);
CREATE TABLE ty_wf_price_tier(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,price_id bigint NOT NULL REFERENCES ty_wf_price(id),lower_quantity numeric(24,6)NOT NULL CHECK(lower_quantity>=0),upper_quantity numeric(24,6),unit_price numeric(24,6)NOT NULL CHECK(unit_price>=0),
 CHECK(upper_quantity IS NULL OR upper_quantity>lower_quantity),EXCLUDE USING gist(price_id WITH =,numrange(lower_quantity,upper_quantity,'[)')WITH &&)
);
CREATE TABLE ty_wf_order(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),contract_id bigint NOT NULL REFERENCES ty_outsource_contract(id),company_id bigint NOT NULL REFERENCES ty_company(id),code text NOT NULL,
 department_id bigint REFERENCES ty_department(id),position_id bigint REFERENCES ty_company_position(id),service_role text NOT NULL,valid_from date NOT NULL,valid_to date NOT NULL,quantity integer NOT NULL CHECK(quantity>0),
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','rejected','cancelled','ended')),revision integer NOT NULL DEFAULT 1,evidence_ref text NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),
 UNIQUE(contract_id,code),CHECK(valid_to>valid_from),CHECK(status<>'approved'OR approved_by IS NOT NULL)
);
CREATE TABLE ty_wf_engagement_review(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),engagement_id bigint NOT NULL REFERENCES ty_outsource_engagement(id),order_id bigint REFERENCES ty_wf_order(id),
 company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),version integer NOT NULL CHECK(version>0),
 legal_kind text NOT NULL CHECK(legal_kind IN('staffing_service','dispatch_cn','payroll_agency','employment_hk')),dispatch_post_kind text CHECK(dispatch_post_kind IN('temporary','auxiliary','substitute')),
 valid_from date NOT NULL,valid_to date NOT NULL,source_hash text NOT NULL,status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','rejected','revoked')),revision integer NOT NULL DEFAULT 1,
 evidence_ref text NOT NULL,qualification_profile_id bigint REFERENCES ty_wf_vendor_profile(id),temporary_post_started_on date,temporary_post_ends_on date,auxiliary_procedure_ref text,substitute_evidence_ref text,
 dispatch_basis_ref text,dispatch_direct_count integer CHECK(dispatch_direct_count>=0),dispatch_count integer CHECK(dispatch_count>=0),dispatch_as_of date,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),review_ref text,
 UNIQUE(engagement_id,version),CHECK(valid_to>valid_from),CHECK(status<>'approved'OR approved_by IS NOT NULL)
);
