 UNIQUE(root_id,version),CHECK(original_quantity IS NULL OR original_quantity>=0),CHECK(source_kind<>'native_time'OR(source_report_id IS NOT NULL AND source_line_id IS NOT NULL AND source_root_id IS NOT NULL AND original_quantity IS NOT NULL AND accepted_quantity<=original_quantity)),CHECK(status<>'approved'OR approved_by IS NOT NULL)
);
