 person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),kind text NOT NULL CHECK(kind IN('employee_disbursement','supplier_custody')),valid_from date NOT NULL,valid_to date NOT NULL,
 status text NOT NULL DEFAULT'pending'CHECK(status IN('pending','approved','rejected','revoked')),revision integer NOT NULL DEFAULT 1,evidence_ref text NOT NULL,source_hash text NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),review_ref text,CHECK(valid_to>valid_from),CHECK(status<>'approved'OR approved_by IS NOT NULL)
