 supplier_id bigint NOT NULL REFERENCES ty_outsource_supplier(id),contract_id bigint NOT NULL REFERENCES ty_outsource_contract(id),mandate_id bigint NOT NULL REFERENCES ty_wf_mandate(id),period date NOT NULL CHECK(extract(day FROM period)=1),pay_subject_key text NOT NULL,currency text NOT NULL CHECK(currency IN('CNY','HKD')),
 source_hash text NOT NULL,target_verified_amount numeric(24,2)NOT NULL CHECK(target_verified_amount>=0),amount numeric(24,2)NOT NULL CHECK(amount>0),fund_parent_id bigint,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','reserved','submitted','unknown','partially_settled','settled','failed','cancelled')),revision integer NOT NULL DEFAULT 1,
 evidence_ref text NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),executed_by bigint REFERENCES sys_account(id),CHECK(status NOT IN('reserved','submitted','unknown','partially_settled','settled')OR(fund_parent_id IS NOT NULL AND approved_by IS NOT NULL AND executed_by IS NOT NULL))
);
