 owner_kind text NOT NULL CHECK(owner_kind IN('vendor_profile','price','order','bill','invoice','payment','thread','mandate')),owner_id bigint NOT NULL,filename text NOT NULL,mime text NOT NULL,byte_length integer NOT NULL CHECK(byte_length BETWEEN 1 AND 8388608),sha256 text NOT NULL CHECK(sha256~'^[0-9a-f]{64}$'),
 content bytea NOT NULL,content_iv text NOT NULL,content_tag text NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(octet_length(content)=byte_length),UNIQUE(group_id,owner_kind,owner_id,sha256)
);
