 as_of date NOT NULL,source_hash text NOT NULL,evidence_ref text NOT NULL,status text NOT NULL DEFAULT'pending'CHECK(status IN('pending','verified','rejected')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),verified_by bigint REFERENCES sys_account(id),review_ref text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(status<>'verified'OR verified_by IS NOT NULL)
);
