 personal_instruction_id bigint REFERENCES ty_wf_personal_instruction(id),UNIQUE(payment_id,bill_line_id)
);
-- Immutable link to the single 227 fund parent survives failed/cancelled paths.
ALTER TABLE ty_wf_personal_instruction ADD CHECK(amount<=target_verified_amount);

CREATE FUNCTION fn_ty_wf_ap_state(p_payable bigint)RETURNS TABLE(target numeric,net_settled numeric,held numeric,available numeric,refund_due numeric,invoice_covered numeric,opening_pending boolean)LANGUAGE sql STABLE SET search_path=''AS $$
 WITH p AS(SELECT x.*,r.opening_status FROM public.ty_wf_payable x JOIN public.ty_wf_bill_root r ON r.id=x.root_id WHERE x.id=p_payable),s AS(SELECT coalesce(sum(CASE WHEN kind='refund'THEN-amount ELSE amount END),0)n FROM public.ty_wf_settlement WHERE payable_id=p_payable),h AS(SELECT coalesce(sum(amount),0)n FROM public.ty_wf_payment WHERE payable_id=p_payable AND status IN('approved','exported','submitted','unknown')),i AS(SELECT coalesce(sum(amount),0)n FROM public.ty_wf_invoice_allocation WHERE payable_id=p_payable)
 SELECT p.target,CASE WHEN p.opening_status='pending'THEN NULL ELSE coalesce(p.opening_net_settled,0)+s.n END,CASE WHEN p.opening_status='pending'THEN NULL ELSE coalesce(p.opening_held,0)+h.n END,
 CASE WHEN p.opening_status='pending'THEN NULL ELSE greatest(0,p.target-coalesce(p.opening_net_settled,0)-s.n-coalesce(p.opening_held,0)-h.n)END,
 CASE WHEN p.opening_status='pending'THEN NULL ELSE greatest(0,coalesce(p.opening_net_settled,0)+s.n-p.target)END,i.n,p.opening_status='pending'FROM p,s,h,i;
$$;
CREATE FUNCTION fn_ty_wf_append_only()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='来源、资金回执和共享证据保留，须追加受控更正，不可改删';END;$$;
DO $$DECLARE name text;BEGIN FOREACH name IN ARRAY ARRAY['ty_wf_ap_entry','ty_wf_invoice','ty_wf_invoice_allocation','ty_wf_settlement','ty_wf_payment_event','ty_wf_message','ty_wf_file','ty_wf_price_tier']LOOP EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.fn_ty_wf_append_only()',name||'_keep',name);END LOOP;END;$$;
ALTER TABLE ty_wf_vendor_profile ADD COLUMN base_hash text NOT NULL;
CREATE FUNCTION fn_ty_wf_supplier_hash(p_id bigint)RETURNS text LANGUAGE sql STABLE SET search_path=''AS $$SELECT md5(jsonb_build_object('id',s.id,'group_id',s.group_id,'owner_company_id',s.owner_company_id,'code',s.code,'name',s.name,'region_code',s.region_code,'currency_code',s.currency_code,'status',s.status,'billing_title',s.billing_title)::text)FROM public.ty_outsource_supplier s WHERE s.id=p_id;$$;
CREATE FUNCTION fn_ty_wf_profile_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE s public.ty_outsource_supplier;j jsonb:=to_jsonb(NEW);o jsonb;k text;a bigint;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供应商已登记资料保留，请另建核定版本';END IF;
 SELECT *INTO s FROM public.ty_outsource_supplier WHERE id=NEW.supplier_id FOR UPDATE;
 IF s.id IS NULL OR s.group_id<>NEW.group_id OR s.owner_company_id IS DISTINCT FROM NEW.company_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供应商资料不能跨集团或改变所属公司';END IF;
 IF(s.region_code='HK'AND NEW.qualification_kind='dispatch_cn')OR(s.region_code='CN'AND NEW.qualification_kind='employment_agency_hk')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='资格类别与实际地区不符';END IF;
 FOREACH k IN ARRAY ARRAY['created_by','approved_by']LOOP a:=(j->>k)::bigint;IF a IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sys_account a LEFT JOIN public.ty_operator_binding b ON b.account_id=a.id LEFT JOIN public.ty_test_account_profile p ON p.account_id=a.id WHERE a.id=(j->>k)::bigint AND a.status='active'AND coalesce(b.status,'active')='active'AND coalesce(b.group_id,p.group_id)=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供应商核定经办和核准人须为本集团有效人员';END IF;END LOOP;
 IF TG_OP='INSERT'THEN
  IF NEW.status<>'draft'OR NEW.revision<>1 OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL OR NEW.version<>(SELECT coalesce(max(version),0)+1 FROM public.ty_wf_vendor_profile WHERE supplier_id=s.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供应商资料须连续新增草稿，不预造核准';END IF;
 ELSE
  o:=to_jsonb(OLD);IF(j-ARRAY['status','revision','approved_by','approved_at','review_ref'])IS DISTINCT FROM(o-ARRAY['status','revision','approved_by','approved_at','review_ref'])OR OLD.status<>'draft'OR NEW.status NOT IN('approved','rejected')OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核供应商资料不可覆写，草稿只推进核准或驳回';END IF;
 END IF;
 IF NEW.status IN('approved','rejected')AND(NEW.approved_by IS NULL OR NEW.approved_at IS NULL OR length(btrim(coalesce(NEW.review_ref,'')))<4 OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供应商收款和资格资料须不同自然人独立核对';END IF;
 IF NEW.status='approved'AND NEW.base_hash IS DISTINCT FROM public.fn_ty_wf_supplier_hash(s.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供应商原资料已变化，请重新核对新版本';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_profile_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_vendor_profile FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_profile_guard();
CREATE TABLE ty_wf_personal_receipt(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,instruction_id bigint NOT NULL REFERENCES ty_wf_personal_instruction(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 provider_namespace text NOT NULL,source_key text NOT NULL,effect text NOT NULL CHECK(effect IN('success','failed','unknown','refund_to_employer','refund_to_supplier','custody_return_to_employer')),
 amount numeric(24,2)NOT NULL CHECK(amount>0),currency text NOT NULL CHECK(currency IN('CNY','HKD')),original_receipt_id bigint REFERENCES ty_wf_personal_receipt(id),occurred_at timestamptz NOT NULL,evidence_ref text NOT NULL,
 source_kind text NOT NULL CHECK(source_kind IN('manually_reviewed_provider_result','synthetic_demo_only')),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','reviewed','rejected','applied')),revision integer NOT NULL DEFAULT 1,
 recorded_by bigint NOT NULL REFERENCES sys_account(id),reviewed_by bigint REFERENCES sys_account(id),reviewed_at timestamptz,review_ref text,applied_by bigint REFERENCES sys_account(id),applied_at timestamptz,
 UNIQUE(group_id,provider_namespace,source_key),CHECK(effect NOT IN('refund_to_employer','refund_to_supplier','custody_return_to_employer')OR original_receipt_id IS NOT NULL),
 CHECK(status NOT IN('reviewed','applied')OR(reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),CHECK(status<>'applied'OR(applied_by IS NOT NULL AND applied_at IS NOT NULL))
);
CREATE TABLE ty_wf_fund_return_link(
 personal_receipt_id bigint NOT NULL REFERENCES ty_wf_personal_receipt(id),payment_allocation_id bigint NOT NULL REFERENCES ty_wf_payment_allocation(id),settlement_id bigint NOT NULL UNIQUE REFERENCES ty_wf_settlement(id),
 amount numeric(24,2)NOT NULL CHECK(amount>0),PRIMARY KEY(personal_receipt_id,payment_allocation_id)
);
CREATE TRIGGER ty_wf_fund_return_keep BEFORE UPDATE OR DELETE ON ty_wf_fund_return_link FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_append_only();
ALTER TABLE ty_wf_price ADD COLUMN base_hash text NOT NULL;
CREATE FUNCTION fn_ty_wf_contract_hash(p_id bigint)RETURNS text LANGUAGE sql STABLE SET search_path=''AS $$SELECT md5(jsonb_build_object('contract',to_jsonb(c),'companies',(SELECT jsonb_agg(company_id ORDER BY company_id)FROM public.ty_outsource_contract_company WHERE contract_id=c.id),'supplier',public.fn_ty_wf_supplier_hash(c.supplier_id))::text)FROM public.ty_outsource_contract c WHERE c.id=p_id;$$;
CREATE FUNCTION fn_ty_wf_price_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE c public.ty_outsource_contract;s public.ty_outsource_supplier;p public.ty_wf_price;j jsonb:=to_jsonb(NEW);o jsonb;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已登记价目保留，新建连续修订';END IF;
 IF TG_TABLE_NAME='ty_wf_price_tier'THEN SELECT*INTO p FROM public.ty_wf_price WHERE id=NEW.price_id FOR UPDATE;IF p.id IS NULL OR p.status<>'draft'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='阶梯只能写入尚未核准价目';END IF;RETURN NEW;END IF;
 SELECT*INTO c FROM public.ty_outsource_contract WHERE id=NEW.contract_id FOR SHARE;SELECT*INTO s FROM public.ty_outsource_supplier WHERE id=c.supplier_id;
 IF c.id IS NULL OR c.group_id<>NEW.group_id OR NEW.currency<>s.currency_code OR NOT EXISTS(SELECT 1 FROM public.ty_outsource_contract_company cc JOIN public.ty_company co ON co.id=cc.company_id WHERE cc.contract_id=c.id AND cc.company_id=NEW.company_id AND co.group_id=NEW.group_id)OR NEW.valid_from<c.valid_from OR NEW.valid_to>c.valid_to+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='价目集团、服务公司、币种与合同日期不符';END IF;
 IF TG_OP='INSERT'THEN IF NEW.status<>'draft'OR NEW.approved_by IS NOT NULL OR NEW.revision<>1 OR NEW.version<>(SELECT coalesce(max(version),0)+1 FROM public.ty_wf_price WHERE contract_id=c.id AND company_id=NEW.company_id AND code=NEW.code)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='价目须新增连续草稿版本';END IF;
 ELSE o:=to_jsonb(OLD);IF(j-ARRAY['status','revision','approved_by','approved_at','review_ref'])IS DISTINCT FROM(o-ARRAY['status','revision','approved_by','approved_at','review_ref'])OR OLD.status<>'draft'OR NEW.status NOT IN('approved','rejected')OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='报价原事实和已核价目不可覆写';END IF;END IF;
 IF NEW.status IN('approved','rejected')AND(NEW.approved_by IS NULL OR NEW.approved_at IS NULL OR length(btrim(coalesce(NEW.review_ref,'')))<4 OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='合同价目须独立复核';END IF;
 IF NEW.status='approved'AND(NEW.base_hash IS DISTINCT FROM public.fn_ty_wf_contract_hash(c.id)OR c.status<>'active'OR s.status<>'active')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='合同或供应商资料已变化/停用，旧价目核准失效';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_price_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_price FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_price_guard();
CREATE TRIGGER ty_wf_tier_guard BEFORE INSERT ON ty_wf_price_tier FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_price_guard();
CREATE TABLE ty_wf_thread_context(
 thread_id bigint PRIMARY KEY REFERENCES ty_outsource_thread(id),group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 audience text NOT NULL CHECK(audience IN('shared','hr_vendor','internal')),title_cipher text NOT NULL,title_iv text NOT NULL,title_tag text NOT NULL,revision integer NOT NULL DEFAULT 1
);
CREATE TRIGGER ty_wf_thread_context_keep BEFORE DELETE ON ty_wf_thread_context FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_append_only();
CREATE FUNCTION fn_ty_wf_chat_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE th public.ty_outsource_thread;c public.ty_outsource_contract;ctx public.ty_wf_thread_context;
BEGIN
 IF TG_TABLE_NAME='ty_wf_thread_context'THEN
 SELECT*INTO th FROM public.ty_outsource_thread WHERE id=NEW.thread_id;SELECT*INTO c FROM public.ty_outsource_contract WHERE id=th.contract_id;
 IF c.id IS NULL OR c.group_id<>NEW.group_id OR NOT EXISTS(SELECT 1 FROM public.ty_outsource_contract_company cc JOIN public.ty_company co ON co.id=cc.company_id WHERE cc.contract_id=c.id AND cc.company_id=NEW.company_id AND co.group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='沟通范围须属于原合同的真实公司';END IF;
 IF TG_OP='UPDATE'AND(to_jsonb(NEW)-'revision')IS DISTINCT FROM(to_jsonb(OLD)-'revision')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='沟通对象、范围和原主题不可改换';END IF;
 RETURN NEW;
 END IF;
 SELECT*INTO th FROM public.ty_outsource_thread WHERE id=NEW.thread_id;SELECT*INTO ctx FROM public.ty_wf_thread_context WHERE thread_id=th.id;SELECT*INTO c FROM public.ty_outsource_contract WHERE id=th.contract_id;
 IF th.id IS NULL OR th.status='resolved'OR coalesce(ctx.audience,'shared')='internal'AND NEW.visibility<>'internal'OR coalesce(ctx.audience,'shared')='hr_vendor'AND NEW.visibility='shared'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已结束或更窄范围的沟通不能公开写入';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sys_account a LEFT JOIN public.ty_operator_binding b ON b.account_id=a.id LEFT JOIN public.ty_test_account_profile p ON p.account_id=a.id WHERE a.id=NEW.author_id AND a.status='active'AND coalesce(b.status,'active')='active'AND coalesce(b.group_id,p.group_id)=c.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='沟通作者须为本集团有效操作人员';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_thread_context_scope BEFORE INSERT OR UPDATE ON ty_wf_thread_context FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_chat_guard();
CREATE TRIGGER ty_wf_message_scope BEFORE INSERT ON ty_wf_message FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_chat_guard();
-- Supplier instructions in this release authorize net wages only. The shared227
-- parent also carries reimbursement but that component must never be consumed here.
ALTER TABLE ty_wf_personal_instruction ADD COLUMN component text NOT NULL DEFAULT'net_wage'CHECK(component='net_wage');

-- Native contracts retain209 IDs while encrypted terms and independent review are explicit.
CREATE TABLE ty_wf_contract_control(
 contract_id bigint PRIMARY KEY REFERENCES ty_outsource_contract(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','rejected','ended')),revision integer NOT NULL DEFAULT 1,
 terms_cipher text NOT NULL,terms_iv text NOT NULL,terms_tag text NOT NULL,evidence_ref text NOT NULL,source_hash text NOT NULL,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),review_ref text,created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE ty_wf_order ADD COLUMN source_hash text NOT NULL;
CREATE FUNCTION fn_ty_wf_relationship_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE c public.ty_outsource_contract;s public.ty_outsource_supplier;e public.ty_employment;eg public.ty_outsource_engagement;o public.ty_wf_order;vp public.ty_wf_vendor_profile;j jsonb:=to_jsonb(NEW);oldj jsonb;allowed text[];pid bigint;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务合同、订单和人员审查保留历史，不可删除';END IF;
 IF TG_TABLE_NAME='ty_wf_engagement_review'THEN
  SELECT*INTO eg FROM public.ty_outsource_engagement WHERE id=NEW.engagement_id;SELECT*INTO c FROM public.ty_outsource_contract WHERE id=eg.contract_id FOR UPDATE;SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
  IF eg.id IS NULL OR eg.person_id<>NEW.person_id OR eg.employment_id<>NEW.employment_id OR c.group_id<>NEW.group_id OR e.company_id<>eg.company_id OR e.person_id<>NEW.person_id OR e.group_id<>NEW.group_id OR NEW.valid_from<eg.valid_from OR NEW.valid_to>coalesce(eg.valid_to,c.valid_to)+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人员审查必须沿原合同真实人员关系和期间，不得移动';END IF;
  SELECT*INTO s FROM public.ty_outsource_supplier WHERE id=c.supplier_id;SELECT*INTO vp FROM public.ty_wf_vendor_profile WHERE id=NEW.qualification_profile_id;
  IF NEW.company_id<>eg.company_id AND NEW.order_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='接收门店派驻必须有明确已核订单，不能把工作地改成新雇佣';END IF;
  IF NEW.order_id IS NOT NULL THEN SELECT*INTO o FROM public.ty_wf_order WHERE id=NEW.order_id;IF o.contract_id<>c.id OR o.company_id<>NEW.company_id OR o.status<>'approved'OR NEW.valid_from<o.valid_from OR NEW.valid_to>o.valid_to THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='派驻须在实际已核订单公司和期间';END IF;END IF;
  IF(c.service_kind='payroll_agency'AND(NEW.legal_kind<>'payroll_agency'OR e.employment_type='outsourced'))OR(c.service_kind='dispatch'AND(NEW.legal_kind<>'dispatch_cn'OR s.region_code<>'CN'OR e.employment_type<>'outsourced'))OR(c.service_kind='staffing_outsource'AND(NEW.legal_kind<>CASE WHEN s.region_code='HK'THEN'employment_hk'ELSE'staffing_service'END OR e.employment_type<>'outsourced'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='用工实质、地区和实际雇佣关系不符，代发不改变雇主';END IF;
  IF NEW.status='approved'THEN
   IF c.service_kind='payroll_agency'AND(NOT EXISTS(SELECT 1 FROM public.fn_ty_hr_verified_legal_subject(e.id,NEW.valid_from)v WHERE v.legal_subject_name=eg.legal_employer_name)OR NOT EXISTS(SELECT 1 FROM public.fn_ty_hr_verified_legal_subject(e.id,NEW.valid_to-1)v WHERE v.legal_subject_name=eg.legal_employer_name))OR c.service_kind<>'payroll_agency'AND eg.legal_employer_name IS DISTINCT FROM e.legal_subject_name THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人员服务核准须承接期间内已核法律雇主，不改写原始雇佣或按供应商推定';END IF;
   IF vp.id IS NULL OR vp.supplier_id<>s.id OR vp.status<>'approved'OR vp.qualification_valid_from>NEW.valid_from OR vp.qualification_valid_to<NEW.valid_to THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='派驻核准须有覆盖实际服务期间的已核供应商资格/适用性依据';END IF;
   IF NEW.legal_kind='dispatch_cn'AND(vp.qualification_kind<>'dispatch_cn'OR NEW.dispatch_post_kind IS NULL OR NEW.dispatch_direct_count IS NULL OR NEW.dispatch_count IS NULL OR NEW.dispatch_as_of IS NULL OR NEW.dispatch_as_of>NEW.valid_from OR length(btrim(coalesce(NEW.dispatch_basis_ref,'')))<4 OR NEW.dispatch_count*10>NEW.dispatch_direct_count+NEW.dispatch_count OR NEW.dispatch_direct_count+NEW.dispatch_count=0)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='内地派遣须核定派遣资格、三性岗位、用工单位直接与派遣总数及10%口径';END IF;
   IF NEW.legal_kind='dispatch_cn'AND((NEW.dispatch_post_kind='temporary'AND(NEW.temporary_post_started_on IS NULL OR NEW.temporary_post_ends_on IS NULL OR NEW.temporary_post_ends_on>NEW.temporary_post_started_on+interval'6 months'OR NEW.temporary_post_ends_on<=NEW.temporary_post_started_on OR NEW.valid_from<NEW.temporary_post_started_on OR NEW.valid_to>NEW.temporary_post_ends_on))OR(NEW.dispatch_post_kind='auxiliary'AND length(btrim(coalesce(NEW.auxiliary_procedure_ref,'')))<4)OR(NEW.dispatch_post_kind='substitute'AND length(btrim(coalesce(NEW.substitute_evidence_ref,'')))<4))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='临时岗位存续不超过6个月；辅助岗位程序和替代依据须分别核定';END IF;
  END IF;
  allowed:=ARRAY['status','revision','approved_by','review_ref'];pid:=NEW.person_id;
 ELSIF TG_TABLE_NAME='ty_wf_order'THEN
  SELECT*INTO c FROM public.ty_outsource_contract WHERE id=NEW.contract_id FOR UPDATE;SELECT*INTO s FROM public.ty_outsource_supplier WHERE id=c.supplier_id;
  IF c.group_id<>NEW.group_id OR NOT EXISTS(SELECT 1 FROM public.ty_outsource_contract_company WHERE contract_id=c.id AND company_id=NEW.company_id)OR NEW.valid_from<c.valid_from OR NEW.valid_to>c.valid_to+1 OR NEW.department_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_department WHERE id=NEW.department_id AND company_id=NEW.company_id)OR NEW.position_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company_position WHERE id=NEW.position_id AND company_id=NEW.company_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务订单部门岗位和日期必须属于合同真实公司';END IF;
  IF NEW.status='approved'AND(c.status<>'active'OR s.status<>'active')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务订单须使用生效合同和供应商';END IF;
  allowed:=ARRAY['status','revision','approved_by'];
 ELSE
  SELECT*INTO c FROM public.ty_outsource_contract WHERE id=NEW.contract_id FOR UPDATE;
  IF c.group_id<>NEW.group_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='合同办理集团不符';END IF;
  allowed:=ARRAY['status','revision','approved_by','review_ref'];
 END IF;
 IF TG_OP='INSERT'THEN
  IF NEW.status<>'draft'OR NEW.revision<>1 OR NEW.approved_by IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务资料必须先登记草稿，再由独立人核准';END IF;
  IF TG_TABLE_NAME='ty_wf_engagement_review'AND (j->>'version')::integer<>(SELECT coalesce(max(version),0)+1 FROM public.ty_wf_engagement_review WHERE engagement_id=(j->>'engagement_id')::bigint)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='关系审查版本须连续';END IF;
 ELSE
  oldj:=to_jsonb(OLD);
  IF(j-allowed)IS DISTINCT FROM(oldj-allowed)OR NEW.revision<>OLD.revision+1 OR NOT(OLD.status='draft'AND NEW.status IN('approved','rejected')OR TG_TABLE_NAME='ty_wf_order'AND OLD.status='approved'AND NEW.status IN('cancelled','ended')OR TG_TABLE_NAME='ty_wf_engagement_review'AND OLD.status='approved'AND NEW.status='revoked'OR TG_TABLE_NAME='ty_wf_contract_control'AND OLD.status='approved'AND NEW.status='ended')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核原事实不可覆写，只可受控结束或新增版本';END IF;
 END IF;
 IF NEW.status IN('approved','rejected')AND(NEW.approved_by IS NULL OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by)OR pid IS NOT NULL AND public.fn_ty_hr_actor_is_person(NEW.approved_by,NEW.group_id,pid))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='经办/同人别名/受益人不能自核派驻服务事项';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_contract_control_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_contract_control FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_relationship_guard();
CREATE TRIGGER ty_wf_order_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_order FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_relationship_guard();
CREATE TRIGGER ty_wf_engagement_review_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_engagement_review FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_relationship_guard();

-- All prepayment applications have explicit economic-line allocation just as bank payments.
CREATE TABLE ty_wf_settlement_allocation(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,settlement_id bigint NOT NULL REFERENCES ty_wf_settlement(id),bill_line_id bigint NOT NULL REFERENCES ty_wf_bill_line(id),
 amount numeric(24,2)NOT NULL CHECK(amount>0),personal_instruction_id bigint REFERENCES ty_wf_personal_instruction(id),UNIQUE(settlement_id,bill_line_id)
);
CREATE TRIGGER ty_wf_settlement_allocation_keep BEFORE UPDATE OR DELETE ON ty_wf_settlement_allocation FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_append_only();
ALTER TABLE ty_wf_fund_return_link DROP CONSTRAINT ty_wf_fund_return_link_pkey;
ALTER TABLE ty_wf_fund_return_link ALTER COLUMN payment_allocation_id DROP NOT NULL;
ALTER TABLE ty_wf_fund_return_link ADD COLUMN advance_allocation_id bigint REFERENCES ty_wf_settlement_allocation(id);
ALTER TABLE ty_wf_fund_return_link ADD COLUMN id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY;
ALTER TABLE ty_wf_fund_return_link ADD CHECK(num_nonnulls(payment_allocation_id,advance_allocation_id)=1);
CREATE UNIQUE INDEX ty_wf_return_payment_once ON ty_wf_fund_return_link(personal_receipt_id,payment_allocation_id)WHERE payment_allocation_id IS NOT NULL;
CREATE UNIQUE INDEX ty_wf_return_advance_once ON ty_wf_fund_return_link(personal_receipt_id,advance_allocation_id)WHERE advance_allocation_id IS NOT NULL;
CREATE FUNCTION fn_ty_wf_custody_funding_state(p_instruction bigint,p_exclude_payment bigint DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE i public.ty_wf_personal_instruction;tr numeric;act numeric;ret numeric;hashval text;bad boolean;
BEGIN
 SELECT*INTO i FROM public.ty_wf_personal_instruction WHERE id=p_instruction;
 IF i.id IS NULL THEN RETURN jsonb_build_object('ready',false,'transferred',NULL,'active',NULL,'returned',NULL,'source_hash',NULL,'reason','instruction_missing');END IF;
 IF p_exclude_payment IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_wf_payment p JOIN public.ty_wf_payment_allocation a ON a.payment_id=p.id WHERE a.personal_instruction_id=i.id AND p.id=p_exclude_payment AND p.status IN('approved','exported','submitted','unknown'))THEN RETURN jsonb_build_object('ready',false,'transferred',NULL,'active',NULL,'returned',NULL,'source_hash',NULL,'reason','exclude_not_own_active_payment');END IF;
 WITH funding AS(
  SELECT a.id::text k,'payment'kind,a.amount,p.status,p.id payment_id,a.bill_line_id,s.id settlement_id
  FROM public.ty_wf_payment_allocation a JOIN public.ty_wf_payment p ON p.id=a.payment_id LEFT JOIN public.ty_wf_settlement s ON s.payment_id=p.id AND s.kind='payment'WHERE a.personal_instruction_id=i.id
  UNION ALL
  SELECT a.id::text,'advance',a.amount,CASE WHEN ad.status='verified'THEN'succeeded'ELSE'unverified_advance'END,NULL,a.bill_line_id,s.id FROM public.ty_wf_settlement_allocation a JOIN public.ty_wf_settlement s ON s.id=a.settlement_id JOIN public.ty_wf_advance ad ON ad.id=s.advance_id WHERE a.personal_instruction_id=i.id AND s.kind='advance_application'
 ), facts AS(SELECT f.*,l.personal_instruction_id linked_i,l.purpose,r.company_id,r.group_id,r.supplier_id,r.currency FROM funding f JOIN public.ty_wf_bill_line l ON l.id=f.bill_line_id JOIN public.ty_wf_bill_version v ON v.id=l.version_id JOIN public.ty_wf_bill_root r ON r.id=v.root_id)
 SELECT coalesce(sum(amount)FILTER(WHERE status='succeeded'AND settlement_id IS NOT NULL),0),coalesce(sum(amount)FILTER(WHERE status IN('approved','exported','submitted','unknown')AND payment_id IS DISTINCT FROM p_exclude_payment),0),coalesce(bool_or(linked_i IS DISTINCT FROM i.id OR purpose<>'agency_funds'OR company_id<>i.company_id OR group_id<>i.group_id OR supplier_id<>i.supplier_id OR currency<>i.currency OR status='succeeded'AND settlement_id IS NULL OR status='unverified_advance'),false),md5(coalesce(jsonb_agg(to_jsonb(facts)ORDER BY kind,k)::text,'[]'))INTO tr,act,bad,hashval FROM facts;
 SELECT coalesce(sum(f.amount),0)INTO ret FROM public.ty_wf_fund_return_link f JOIN public.ty_wf_personal_receipt r ON r.id=f.personal_receipt_id JOIN public.ty_wf_settlement s ON s.id=f.settlement_id WHERE r.instruction_id=i.id AND r.effect IN('refund_to_employer','custody_return_to_employer')AND r.status IN('reviewed','applied')AND s.kind='refund';
 IF bad OR ret>tr OR tr-ret+act>i.amount THEN RETURN jsonb_build_object('ready',false,'transferred',NULL,'active',NULL,'returned',NULL,'source_hash',hashval,'reason','custody_provenance_or_amount_conflict');END IF;
 RETURN jsonb_build_object('ready',true,'transferred',tr::text,'active',act::text,'returned',ret::text,'source_hash',md5(hashval||':'||ret::text||':'||i.id::text));
END;$$;
-- Accepted quantity and financial lines keep exact source units; displayed hours may round, priced money does not.
ALTER TABLE ty_wf_acceptance_root ADD COLUMN slice_end date;
ALTER TABLE ty_wf_acceptance_root ADD CHECK(slice_end IS NULL OR slice_end>work_date);
ALTER TABLE ty_wf_bill_line ADD COLUMN base_quantity numeric(24,6) CHECK(base_quantity IS NULL OR base_quantity>=0);
ALTER TABLE ty_wf_price ADD COLUMN tax_basis text NOT NULL DEFAULT'pending'CHECK(tax_basis IN('gross','net','not_applicable_reviewed','pending'));
ALTER TABLE ty_wf_bill_version ADD COLUMN vendor_confirmation_kind text CHECK(vendor_confirmation_kind IN('portal_confirmed','manually_registered_evidence'));

ALTER TABLE ty_wf_acceptance_root DROP CONSTRAINT ty_wf_acceptance_root_metric_check;
ALTER TABLE ty_wf_acceptance_root ADD CHECK(metric IN('service_minutes','shifts','service_days','person_months','deliverables'));
ALTER TABLE ty_wf_acceptance_version ADD COLUMN quantity_through_date date;
ALTER TABLE ty_wf_acceptance_version ADD CHECK(source_kind<>'native_time'OR quantity_through_date IS NOT NULL);
ALTER TABLE ty_wf_acceptance_version ADD COLUMN source_head_revision integer;
ALTER TABLE ty_wf_acceptance_version ADD COLUMN report_content_hash text;
ALTER TABLE ty_wf_acceptance_version ADD COLUMN coverage_from date;
ALTER TABLE ty_wf_acceptance_version ADD COLUMN coverage_to date;
ALTER TABLE ty_wf_acceptance_version ADD CHECK(coverage_to IS NULL OR coverage_from IS NOT NULL AND coverage_to>coverage_from);
CREATE TABLE ty_wf_acceptance_allocation(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,acceptance_version_id bigint NOT NULL REFERENCES ty_wf_acceptance_version(id),
 work_company_id bigint NOT NULL REFERENCES ty_company(id),order_id bigint REFERENCES ty_wf_order(id),quantity numeric(24,6)NOT NULL CHECK(quantity>=0),coverage_from date NOT NULL,coverage_to date NOT NULL CHECK(coverage_to>coverage_from),
 source_fact_keys jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(source_fact_keys)='array'),allocation_kind text NOT NULL CHECK(allocation_kind IN('source_verified','external_reviewed')),evidence_ref text NOT NULL,UNIQUE(acceptance_version_id,work_company_id,coverage_from,coverage_to)
);
ALTER TABLE ty_wf_bill_line ADD COLUMN acceptance_allocation_id bigint REFERENCES ty_wf_acceptance_allocation(id);

CREATE FUNCTION fn_ty_wf_acceptance_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_wf_acceptance_root;e public.ty_employment;eg public.ty_outsource_engagement;tr public.ty_time_report_root;v public.ty_time_report_version;qty numeric;expected text;j jsonb:=to_jsonb(NEW);
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务验收原记录保留，须新增受控版本';END IF;
 IF TG_TABLE_NAME='ty_wf_acceptance_root'THEN
  IF NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.company_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='验收公司集团不符';END IF;
  IF NEW.person_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_employment WHERE id=NEW.employment_id AND person_id=NEW.person_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='验收人和真实雇佣关系不符';END IF;
  IF TG_OP='UPDATE'AND((j-ARRAY['current_version_id','revision'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['current_version_id','revision'])OR NEW.revision<>OLD.revision+1 OR NOT EXISTS(SELECT 1 FROM public.ty_wf_acceptance_version x WHERE x.id=NEW.current_version_id AND x.root_id=NEW.id AND x.status='approved'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='验收身份不变，当前指针只能沿同根已核新版本推进';END IF;
  RETURN NEW;
 END IF;
 SELECT*INTO r FROM public.ty_wf_acceptance_root WHERE id=NEW.root_id FOR UPDATE;
 IF TG_OP='INSERT'THEN
  IF NEW.status<>'draft'OR NEW.revision<>1 OR NEW.approved_by IS NOT NULL OR NEW.version<>(SELECT coalesce(max(version),0)+1 FROM public.ty_wf_acceptance_version WHERE root_id=r.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务验收须连续登记草稿';END IF;
 ELSE IF(j-ARRAY['status','revision','approved_by','review_ref'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','approved_by','review_ref'])OR OLD.status<>'draft'OR NEW.status NOT IN('approved','rejected','cancelled')OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='验收事实不可覆写，只可复核或作废草稿';END IF;END IF;
 IF NEW.engagement_id IS NOT NULL THEN
  SELECT*INTO eg FROM public.ty_outsource_engagement WHERE id=NEW.engagement_id;
  IF eg.person_id IS DISTINCT FROM r.person_id OR eg.employment_id IS DISTINCT FROM r.employment_id OR eg.company_id<>r.company_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务验收须沿同一真实人员关系和服务期间';END IF;
 END IF;
 IF NEW.status='approved'THEN
  IF NEW.approved_by IS NULL OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by)OR r.person_id IS NOT NULL AND public.fn_ty_hr_actor_is_person(NEW.approved_by,r.group_id,r.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务量须独立复核，不能本人或代理自核';END IF;
  IF NEW.source_kind='native_time'THEN
   SELECT*INTO tr FROM public.ty_time_report_root WHERE id=NEW.source_root_id FOR SHARE;SELECT*INTO v FROM public.ty_time_report_version WHERE id=NEW.source_report_id;
   SELECT sum(l.worked_minutes+l.overtime_minutes)INTO qty FROM public.ty_time_report_line l WHERE l.report_id=v.id AND l.person_id=r.person_id AND l.employment_id=r.employment_id AND l.scope_company_id=r.company_id AND l.receiving_store_only=(tr.perspective='receiving')AND(l.work_date IS NULL OR l.work_date<=NEW.quantity_through_date);
   IF tr.id IS NULL OR tr.current_report_id<>v.id OR v.status<>'confirmed'OR tr.group_id<>r.group_id OR tr.employment_id<>r.employment_id OR tr.person_id<>r.person_id OR tr.owner_company_id<>r.company_id OR tr.period<>r.work_date OR tr.perspective<>'employer'OR NEW.coverage_to IS DISTINCT FROM(NEW.quantity_through_date+1)OR tr.head_revision IS DISTINCT FROM NEW.source_head_revision OR v.source_hash IS DISTINCT FROM NEW.report_content_hash OR r.slice_end IS DISTINCT FROM(tr.period+interval'1 month')::date OR NEW.unit<>'minute'OR r.metric<>'service_minutes'OR qty IS NULL OR EXISTS(SELECT 1 FROM public.ty_time_report_line l WHERE l.report_id=v.id AND l.person_id=r.person_id AND l.employment_id=r.employment_id AND l.scope_company_id=r.company_id AND l.receiving_store_only=(tr.perspective='receiving')AND(l.worked_minutes IS NULL OR l.overtime_minutes IS NULL)AND(l.work_date IS NULL OR l.work_date<=NEW.quantity_through_date))OR NEW.original_quantity IS DISTINCT FROM qty OR NEW.accepted_quantity<>qty OR NOT EXISTS(SELECT 1 FROM public.ty_time_report_line WHERE id=NEW.source_line_id AND report_id=v.id AND employment_id=r.employment_id AND scope_company_id=r.company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='验收须绑定当前已核完整月实际工时，未知不得当0；版本不可伪造';END IF;
  END IF;
 END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_acceptance_root_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_acceptance_root FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_acceptance_guard();
CREATE TRIGGER ty_wf_acceptance_version_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_acceptance_version FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_acceptance_guard();
CREATE FUNCTION fn_ty_wf_bill_hash(p_version bigint)RETURNS text LANGUAGE sql STABLE SET search_path=''AS $$SELECT md5(jsonb_build_object('root',to_jsonb(r)-ARRAY['current_version_id','revision','opening_status','opening_ref','opening_verified_by'],'lines',(SELECT jsonb_agg(to_jsonb(l)ORDER BY l.line_key)FROM public.ty_wf_bill_line l WHERE l.version_id=v.id))::text)FROM public.ty_wf_bill_version v JOIN public.ty_wf_bill_root r ON r.id=v.root_id WHERE v.id=p_version;$$;
CREATE FUNCTION fn_ty_wf_bill_integrity()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_wf_bill_root;v public.ty_wf_bill_version;c public.ty_outsource_contract;p public.ty_wf_price;av public.ty_wf_acceptance_version;ar public.ty_wf_acceptance_root;alloc public.ty_wf_acceptance_allocation;i public.ty_wf_personal_instruction;cat public.ty_pay_item_catalog;used numeric;qty numeric;otherid bigint;j jsonb:=to_jsonb(NEW);
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='对账与费用原版本保留，只可追加更正';END IF;
 IF TG_TABLE_NAME='ty_wf_bill_root'THEN
  SELECT*INTO c FROM public.ty_outsource_contract WHERE id=NEW.contract_id;
  IF c.group_id<>NEW.group_id OR c.supplier_id<>NEW.supplier_id OR NOT EXISTS(SELECT 1 FROM public.ty_outsource_contract_company cc JOIN public.ty_outsource_supplier s ON s.id=c.supplier_id WHERE cc.contract_id=c.id AND cc.company_id=NEW.company_id AND s.currency_code=NEW.currency)OR NEW.period>c.valid_to OR NEW.period+interval'1 month'<=c.valid_from THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='账单须属于同合同公司、月份和币种';END IF;
  IF TG_OP='UPDATE'AND((j-ARRAY['current_version_id','revision','opening_status','opening_ref','opening_verified_by'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['current_version_id','revision','opening_status','opening_ref','opening_verified_by'])OR NEW.revision<>OLD.revision+1)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='账单稳定身份不可改换';END IF;
  IF NEW.current_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_wf_bill_version WHERE id=NEW.current_version_id AND root_id=NEW.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='账单指针须为本根真实版本';END IF;
  RETURN NEW;
 END IF;
 IF TG_TABLE_NAME='ty_wf_bill_line'THEN
  SELECT*INTO v FROM public.ty_wf_bill_version WHERE id=NEW.version_id FOR UPDATE;SELECT*INTO r FROM public.ty_wf_bill_root WHERE id=v.root_id;SELECT*INTO cat FROM public.ty_pay_item_catalog WHERE code=NEW.item_code;
  IF TG_OP<>'INSERT'OR v.status<>'draft'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='对账明细仅在创建草稿时追加，后续须另建版本';END IF;
  IF NEW.purpose IN('service_fee','adjustment')AND(cat.category<>'procurement_service'OR NEW.cost_membership NOT IN('independent','included_in_parent'))OR NEW.purpose='agency_funds'AND(cat.code<>'AGENCY_NET_WAGE_FUNDS'OR NEW.cost_membership<>'excluded')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务费与受托净工资资金不可混作工资或重复成本';END IF;
  IF NEW.person_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_employment WHERE id=NEW.employment_id AND person_id=NEW.person_id AND group_id=r.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='费用人员关系不符';END IF;
  IF NEW.source_kind='accepted_service'THEN
   SELECT*INTO av FROM public.ty_wf_acceptance_version WHERE id=NEW.acceptance_version_id;SELECT*INTO ar FROM public.ty_wf_acceptance_root WHERE id=av.root_id;SELECT*INTO alloc FROM public.ty_wf_acceptance_allocation WHERE id=NEW.acceptance_allocation_id;SELECT*INTO p FROM public.ty_wf_price WHERE id=NEW.price_id;
   IF av.id IS NULL OR av.status<>'approved'OR ar.current_version_id<>av.id OR alloc.id IS NULL OR alloc.acceptance_version_id<>av.id OR alloc.work_company_id<>r.company_id OR ar.group_id<>r.group_id OR ar.person_id IS DISTINCT FROM NEW.person_id OR ar.employment_id IS DISTINCT FROM NEW.employment_id OR p.id IS NULL OR p.status<>'approved'OR p.company_id<>r.company_id OR p.contract_id<>r.contract_id OR p.currency<>r.currency OR alloc.coverage_from<p.valid_from OR alloc.coverage_to>p.valid_to OR p.tax_basis='pending'OR p.tax_basis='net'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务费用须沿当前已核验收和覆盖全部切片的含税/明确适用价目；缺税口径不得猜0';END IF;
   IF NOT EXISTS(SELECT 1 FROM public.ty_wf_engagement_review er JOIN public.ty_outsource_engagement eg ON eg.id=er.engagement_id WHERE eg.contract_id=r.contract_id AND er.company_id=r.company_id AND er.person_id=ar.person_id AND er.employment_id=ar.employment_id AND er.status='approved'AND er.valid_from<=alloc.coverage_from AND er.valid_to>=alloc.coverage_to)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='本合同工作地和期间的真实人员服务关系尚未核定，不得借他人供应商关系结算';END IF;
   IF NEW.base_or_extra='base'AND(p.component<>'base'OR NEW.base_quantity IS NULL)OR NEW.base_or_extra='extra'AND p.component='base'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='基础数量和独立附加用途须分列，不得借附加重复基础量';END IF;
  ELSIF NEW.source_kind='native_payroll'THEN
   SELECT*INTO i FROM public.ty_wf_personal_instruction WHERE id=NEW.personal_instruction_id;
   IF NEW.purpose<>'agency_funds'OR i.id IS NULL OR i.group_id<>r.group_id OR i.company_id<>r.company_id OR i.contract_id<>r.contract_id OR i.supplier_id<>r.supplier_id OR i.period<>r.period OR i.currency<>r.currency OR i.person_id IS DISTINCT FROM NEW.person_id OR i.employment_id IS DISTINCT FROM NEW.employment_id OR NEW.amount<>i.amount OR NEW.source_hash<>i.source_hash OR i.status NOT IN('approved','reserved','submitted','unknown','partially_settled','settled')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代发资金须绑定同人同月真实已核净工资指令，不得用任意金额或报销份额';END IF;
  ELSIF NEW.source_kind='approved_adjustment'THEN IF NEW.purpose<>'adjustment'OR length(btrim(NEW.evidence_ref))<4 OR NEW.personal_instruction_id IS NOT NULL OR NEW.base_or_extra<>'not_quantity'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='独立服务费用更正须明确依据，不可冒充工资资金或工时';END IF;
  ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='不支持的费用来源';END IF;
  RETURN NEW;
 END IF;
 SELECT*INTO r FROM public.ty_wf_bill_root WHERE id=NEW.root_id FOR UPDATE;
 IF TG_OP='INSERT'THEN
  IF NEW.status<>'draft'OR NEW.revision<>1 OR NEW.version<>(SELECT coalesce(max(version),0)+1 FROM public.ty_wf_bill_version WHERE root_id=r.id)OR NEW.parent_version_id IS DISTINCT FROM r.current_version_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='对账须新增连续草稿并承接上一真实版本';END IF;
 ELSE
  IF(j-ARRAY['status','revision','source_hash','target','reviewed_by','review_ref','vendor_confirmed_by','vendor_ref','shared_by','shared_at','posted_by','posted_at','vendor_confirmation_kind'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','source_hash','target','reviewed_by','review_ref','vendor_confirmed_by','vendor_ref','shared_by','shared_at','posted_by','posted_at','vendor_confirmation_kind'])OR NEW.revision<>OLD.revision+1 OR NOT(OLD.status='draft'AND NEW.status IN('draft','reviewed','cancelled')OR OLD.status='reviewed'AND NEW.status='shared'OR OLD.status='shared'AND NEW.status IN('agreed','disputed')OR OLD.status='agreed'AND NEW.status='posted')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='账单只能按真实核对、共享、对账和应付顺序推进';END IF;
  IF OLD.status<>'draft'AND(NEW.source_hash IS DISTINCT FROM OLD.source_hash OR NEW.target IS DISTINCT FROM OLD.target)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核账单金额和源版本不可覆写';END IF;
 END IF;
 IF NEW.status IN('reviewed','shared','agreed','posted')THEN
  IF EXISTS(SELECT 1 FROM public.ty_wf_bill_line l JOIN public.ty_wf_personal_instruction ins ON ins.id=l.personal_instruction_id WHERE l.version_id=NEW.id AND l.purpose='agency_funds'AND(ins.fund_parent_id IS NULL OR ins.status NOT IN('reserved','submitted','unknown','partially_settled','settled')))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='代发账单只核准真实共同工资占用，草稿指令不是另一份应付';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.ty_wf_bill_line WHERE version_id=NEW.id)OR NEW.target IS DISTINCT FROM(SELECT sum(amount)FROM public.ty_wf_bill_line WHERE version_id=NEW.id AND payable_effect='additive')OR NEW.reviewed_by IS NULL OR public.fn_ty_hr_same_human(NEW.reviewed_by,NEW.created_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='非空账单须逐行金额守恒及不同自然人复核';END IF;
  FOR otherid IN SELECT DISTINCT ax.root_id FROM public.ty_wf_bill_line l JOIN public.ty_wf_acceptance_version ax ON ax.id=l.acceptance_version_id WHERE l.version_id=NEW.id AND l.base_or_extra='base'ORDER BY ax.root_id LOOP
   PERFORM 1 FROM public.ty_wf_acceptance_root WHERE id=otherid FOR UPDATE;
   SELECT accepted_quantity INTO qty FROM public.ty_wf_acceptance_version WHERE id=(SELECT current_version_id FROM public.ty_wf_acceptance_root WHERE id=otherid);
   SELECT coalesce(sum(l.base_quantity),0)INTO used FROM public.ty_wf_bill_line l JOIN public.ty_wf_acceptance_version ax ON ax.id=l.acceptance_version_id JOIN public.ty_wf_bill_version b ON b.id=l.version_id JOIN public.ty_wf_bill_root br ON br.id=b.root_id WHERE ax.root_id=otherid AND l.base_or_extra='base'AND(b.id=NEW.id OR b.root_id<>NEW.root_id AND b.id=(SELECT z.id FROM public.ty_wf_bill_version z WHERE z.root_id=b.root_id AND z.status IN('reviewed','shared','agreed','posted')ORDER BY z.version DESC LIMIT 1));
   IF qty IS NULL OR used>qty THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一基础工作事实跨合同累计不能超过当前已核服务量，换版不新造数量';END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_bill_root_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_bill_root FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_bill_integrity();
CREATE TRIGGER ty_wf_bill_version_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_bill_version FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_bill_integrity();
CREATE TRIGGER ty_wf_bill_line_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_bill_line FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_bill_integrity();
ALTER TABLE ty_wf_bill_line ADD COLUMN pricing_offset numeric(24,6)NOT NULL DEFAULT 0 CHECK(pricing_offset>=0);
ALTER TABLE ty_wf_bill_line ADD COLUMN payable_effect text NOT NULL DEFAULT'additive'CHECK(payable_effect IN('additive','included_detail'));
CREATE FUNCTION fn_ty_wf_price_charge(p_price bigint,p_quantity numeric,p_offset numeric DEFAULT 0)RETURNS numeric LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE p public.ty_wf_price;x public.ty_wf_price_tier;total numeric:=0;prior numeric:=0;upperq numeric;part numeric;lastq numeric:=0;has_tiers boolean:=false;
BEGIN
 SELECT*INTO p FROM public.ty_wf_price WHERE id=p_price;
 IF p.id IS NULL OR p_quantity<0 OR p_offset<0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='价目和数量待核';END IF;
 FOR x IN SELECT*FROM public.ty_wf_price_tier WHERE price_id=p.id ORDER BY lower_quantity LOOP
  has_tiers:=true;IF x.lower_quantity<>lastq THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='阶梯缺档';END IF;
  total:=total+greatest(0,least(p_offset+p_quantity,coalesce(x.upper_quantity,p_offset+p_quantity))-x.lower_quantity)*x.unit_price;
  prior:=prior+greatest(0,least(p_offset,coalesce(x.upper_quantity,p_offset))-x.lower_quantity)*x.unit_price;
  lastq:=x.upper_quantity;
 END LOOP;
 IF has_tiers AND lastq IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='阶梯最终上限待核';END IF;
 IF NOT has_tiers THEN total:=(p_offset+p_quantity)*p.unit_price;prior:=p_offset*p.unit_price;END IF;
 IF p.rounding='aggregate_half_up_2'THEN RETURN round(total,2)-round(prior,2);END IF;
 RETURN round(total-prior,2);
END;$$;
-- Validate exact amounts and metadata independently from browser payloads.
CREATE FUNCTION fn_ty_wf_line_math_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_wf_price;v public.ty_wf_bill_version;ar public.ty_wf_acceptance_root;av public.ty_wf_acceptance_version;expected numeric;quantity numeric;basis numeric;
BEGIN
 IF NEW.payable_effect='included_detail'AND NEW.cost_membership<>'included_in_parent'OR NEW.cost_membership='included_in_parent'AND NEW.payable_effect<>'included_detail'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='父项已含明细不得再次形成应付和成本';END IF;
 IF NEW.source_kind='accepted_service'THEN
  SELECT*INTO p FROM public.ty_wf_price WHERE id=NEW.price_id;SELECT*INTO av FROM public.ty_wf_acceptance_version WHERE id=NEW.acceptance_version_id;SELECT*INTO ar FROM public.ty_wf_acceptance_root WHERE id=av.root_id;
  IF p.component='fixed_fee'AND p.unit='period'THEN
   IF NEW.quantity<>1 OR NEW.base_or_extra<>'extra'OR EXISTS(SELECT 1 FROM public.ty_wf_bill_line l JOIN public.ty_wf_price pr ON pr.id=l.price_id WHERE l.version_id=NEW.version_id AND pr.code=p.code AND pr.component='fixed_fee'AND pr.unit='period'AND l.payable_effect='additive')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='合同期固定费只计一次，不能按员工重复相加';END IF;expected:=public.fn_ty_wf_price_charge(p.id,1,0);
  ELSIF p.component='minimum_topup'THEN
   IF EXISTS(SELECT 1 FROM public.ty_wf_bill_line l JOIN public.ty_wf_price pr ON pr.id=l.price_id WHERE l.version_id=NEW.version_id AND pr.component='minimum_topup')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一合同月保底义务只计一次';END IF;
   SELECT coalesce(sum(l.amount),0)INTO basis FROM public.ty_wf_bill_line l WHERE l.version_id=NEW.version_id AND l.purpose='service_fee'AND l.payable_effect='additive';expected:=greatest(0,p.minimum_target-basis);
   IF NEW.quantity<>1 OR NEW.base_or_extra<>'extra'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='最低服务保障为独立差额项，不是重复基础服务量';END IF;
  ELSE
   IF NEW.base_quantity IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务费用必须保留未折算基础数量';END IF;
   IF av.unit='minute'AND p.unit='hour'THEN quantity:=NEW.base_quantity/60;ELSIF av.unit=p.unit OR av.unit='result'AND p.unit='result'THEN quantity:=NEW.base_quantity;ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务来源与价目单位不符';END IF;
   IF abs(NEW.quantity-quantity)>0.00000051 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='显示数量与实际基础单位不符';END IF;
   SELECT coalesce(sum(CASE WHEN av2.unit='minute'AND pr.unit='hour'THEN l.base_quantity/60 ELSE l.base_quantity END),0)INTO basis FROM public.ty_wf_bill_line l JOIN public.ty_wf_price pr ON pr.id=l.price_id JOIN public.ty_wf_acceptance_version av2 ON av2.id=l.acceptance_version_id WHERE l.version_id=NEW.version_id AND l.price_id=p.id;
   IF abs(NEW.pricing_offset-basis)>0.00000051 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='阶梯必须沿本期累计服务量，不能逐行重复从0计';END IF;
   expected:=public.fn_ty_wf_price_charge(p.id,quantity,basis);
  END IF;
  IF NEW.amount<>expected OR NEW.unit_price<>p.unit_price THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务金额必须由精确来源和已核价目计算';END IF;
 END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_line_math BEFORE INSERT ON ty_wf_bill_line FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_line_math_guard();
CREATE FUNCTION fn_ty_wf_ap_post(p_version bigint,p_actor bigint)RETURNS bigint LANGUAGE plpgsql SET search_path=''AS $$
DECLARE b public.ty_wf_bill_version;r public.ty_wf_bill_root;p public.ty_wf_payable;eid bigint;
BEGIN
 SELECT*INTO b FROM public.ty_wf_bill_version WHERE id=p_version FOR UPDATE;SELECT*INTO r FROM public.ty_wf_bill_root WHERE id=b.root_id FOR UPDATE;
 IF b.status<>'agreed'OR r.current_version_id<>b.id OR public.fn_ty_hr_same_human(p_actor,b.created_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='只有当前双方已确认且独立办理的对账版本可记应付';END IF;
 INSERT INTO public.ty_wf_payable(root_id)VALUES(r.id)ON CONFLICT(root_id)DO NOTHING;SELECT*INTO p FROM public.ty_wf_payable WHERE root_id=r.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.ty_wf_ap_entry WHERE version_id=b.id)THEN RETURN p.id;END IF;
 INSERT INTO public.ty_wf_ap_entry(payable_id,version_id,prior_target,target,delta,posted_by)VALUES(p.id,b.id,p.target,b.target,b.target-p.target,p_actor)RETURNING id INTO eid;
 UPDATE public.ty_wf_payable SET target=b.target,last_version_id=b.id,revision=revision+1 WHERE id=p.id;
 UPDATE public.ty_wf_bill_version SET status='posted',posted_by=p_actor,posted_at=clock_timestamp(),revision=revision+1 WHERE id=b.id;
 RETURN p.id;
END;$$;
-- Excluding an already approved payment is solely an execution check of that same row.
DROP FUNCTION fn_ty_wf_ap_state(bigint);
CREATE FUNCTION fn_ty_wf_ap_state(p_payable bigint,p_exclude_payment bigint DEFAULT NULL)RETURNS TABLE(target numeric,net_settled numeric,held numeric,available numeric,refund_due numeric,invoice_covered numeric,opening_pending boolean)LANGUAGE sql STABLE SET search_path=''AS $$
 WITH p AS(SELECT x.*,r.opening_status FROM public.ty_wf_payable x JOIN public.ty_wf_bill_root r ON r.id=x.root_id WHERE x.id=p_payable),s AS(SELECT coalesce(sum(CASE WHEN kind='refund'THEN-amount ELSE amount END),0)n FROM public.ty_wf_settlement WHERE payable_id=p_payable),h AS(SELECT coalesce(sum(amount),0)n FROM public.ty_wf_payment WHERE payable_id=p_payable AND status IN('approved','exported','submitted','unknown')AND id IS DISTINCT FROM p_exclude_payment),i AS(SELECT coalesce(sum(amount),0)n FROM public.ty_wf_invoice_allocation WHERE payable_id=p_payable)
 SELECT p.target,CASE WHEN p.opening_status='pending'THEN NULL ELSE coalesce(p.opening_net_settled,0)+s.n END,CASE WHEN p.opening_status='pending'THEN NULL ELSE coalesce(p.opening_held,0)+h.n END,CASE WHEN p.opening_status='pending'THEN NULL ELSE greatest(0,p.target-coalesce(p.opening_net_settled,0)-s.n-coalesce(p.opening_held,0)-h.n)END,CASE WHEN p.opening_status='pending'THEN NULL ELSE greatest(0,coalesce(p.opening_net_settled,0)+s.n-p.target)END,i.n,p.opening_status='pending'FROM p,s,h,i;
$$;
-- Reconstruct the AP root from immutable target-delta entries, never from a claimed payment status.
CREATE FUNCTION fn_ty_wf_ap_conservation()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE rootkey bigint;p public.ty_wf_payable;o public.ty_wf_opening;total numeric;lastid bigint;bad boolean;
BEGIN
 IF TG_TABLE_NAME='ty_wf_bill_version'THEN rootkey:=NEW.root_id;ELSIF TG_TABLE_NAME='ty_wf_payable'THEN rootkey:=NEW.root_id;ELSE SELECT root_id INTO rootkey FROM public.ty_wf_payable WHERE id=NEW.payable_id;END IF;
 SELECT*INTO p FROM public.ty_wf_payable WHERE root_id=rootkey;IF p.id IS NULL THEN RETURN NULL;END IF;
 SELECT*INTO o FROM public.ty_wf_opening WHERE root_id=rootkey AND status='verified';
 SELECT coalesce(sum(delta),0)+coalesce(o.recognised_target,0)INTO total FROM public.ty_wf_ap_entry WHERE payable_id=p.id;
 SELECT e.version_id INTO lastid FROM public.ty_wf_ap_entry e JOIN public.ty_wf_bill_version v ON v.id=e.version_id WHERE e.payable_id=p.id ORDER BY v.version DESC LIMIT 1;
 SELECT EXISTS(SELECT 1 FROM public.ty_wf_ap_entry e JOIN public.ty_wf_bill_version v ON v.id=e.version_id WHERE e.payable_id=p.id AND(v.root_id<>rootkey OR v.status<>'posted'OR v.target<>e.target OR e.posted_by<>v.posted_by OR public.fn_ty_hr_same_human(e.posted_by,v.created_by)))INTO bad;
 IF p.target<>total OR p.last_version_id IS DISTINCT FROM lastid OR bad OR o.id IS NOT NULL AND(p.opening_net_settled IS DISTINCT FROM o.net_settled OR p.opening_held IS DISTINCT FROM o.held OR p.opening_ref IS DISTINCT FROM o.evidence_ref)OR o.id IS NULL AND(p.opening_net_settled IS NOT NULL OR p.opening_held IS NOT NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='应付目标与实际版差、独立记账或已核期初不守恒';END IF;
 IF EXISTS(SELECT 1 FROM(SELECT e.prior_target,lag(e.target,1,coalesce(o.recognised_target,0))OVER(ORDER BY v.version)expected_prior FROM public.ty_wf_ap_entry e JOIN public.ty_wf_bill_version v ON v.id=e.version_id WHERE e.payable_id=p.id)x WHERE x.prior_target<>x.expected_prior)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='应付各版须承接上一累计目标，不得重复确认全额';END IF;
 RETURN NULL;
END;$$;
CREATE CONSTRAINT TRIGGER ty_wf_ap_target_consistent AFTER INSERT OR UPDATE ON ty_wf_payable DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_ap_conservation();
CREATE CONSTRAINT TRIGGER ty_wf_ap_entry_consistent AFTER INSERT ON ty_wf_ap_entry DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_ap_conservation();
CREATE CONSTRAINT TRIGGER ty_wf_ap_bill_consistent AFTER INSERT OR UPDATE ON ty_wf_bill_version DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_ap_conservation();
-- One reviewed bank fact can feed distinct journals, with a separate cap in each journal.
CREATE TABLE ty_wf_bank_receipt(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),supplier_id bigint NOT NULL REFERENCES ty_outsource_supplier(id),
 currency text NOT NULL CHECK(currency IN('CNY','HKD')),provider_namespace text NOT NULL,source_key text NOT NULL,kind text NOT NULL CHECK(kind IN('payment_out','supplier_refund_in','advance_out','transfer_not_executed')),
 amount numeric(24,2)NOT NULL CHECK(amount>0),occurred_on date NOT NULL,evidence_ref text NOT NULL,status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','verified','rejected')),revision integer NOT NULL DEFAULT 1,
 recorded_by bigint NOT NULL REFERENCES sys_account(id),reviewed_by bigint REFERENCES sys_account(id),review_ref text,reviewed_at timestamptz,UNIQUE(group_id,provider_namespace,source_key)
);
ALTER TABLE ty_wf_settlement ADD COLUMN bank_receipt_id bigint REFERENCES ty_wf_bank_receipt(id);
ALTER TABLE ty_wf_personal_receipt ADD COLUMN bank_receipt_id bigint REFERENCES ty_wf_bank_receipt(id);
ALTER TABLE ty_wf_advance ADD COLUMN bank_receipt_id bigint REFERENCES ty_wf_bank_receipt(id);
ALTER TABLE ty_wf_payment_event ADD COLUMN bank_receipt_id bigint REFERENCES ty_wf_bank_receipt(id);
CREATE FUNCTION fn_ty_wf_bank_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE j jsonb:=to_jsonb(NEW);s public.ty_outsource_supplier;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='银行原事实须保留，不可删除';END IF;
 SELECT*INTO s FROM public.ty_outsource_supplier WHERE id=NEW.supplier_id;
 IF s.group_id<>NEW.group_id OR s.currency_code<>NEW.currency OR NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.company_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='银行事实须对应实际同集团公司供应商和币种';END IF;
 IF TG_OP='INSERT'THEN IF NEW.status<>'draft'OR NEW.revision<>1 OR NEW.reviewed_by IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='银行证据先登记，不能伪造已查验回执';END IF;
 ELSE IF(j-ARRAY['status','revision','reviewed_by','review_ref','reviewed_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','reviewed_by','review_ref','reviewed_at'])OR OLD.status<>'draft'OR NEW.status NOT IN('verified','rejected')OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='银行事实不可覆写，只可独立核定一次';END IF;END IF;
 IF NEW.status IN('verified','rejected')AND(NEW.reviewed_by IS NULL OR NEW.reviewed_at IS NULL OR length(btrim(coalesce(NEW.review_ref,'')))<4 OR public.fn_ty_hr_same_human(NEW.reviewed_by,NEW.recorded_by))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='银行证据须不同自然人复核，导出或供应商确认不等于实付';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_bank_receipt_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_bank_receipt FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_bank_guard();
CREATE FUNCTION fn_ty_wf_finance_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_wf_payable;r public.ty_wf_bill_root;b public.ty_wf_bank_receipt;adv public.ty_wf_advance;orig public.ty_wf_settlement;vp public.ty_wf_vendor_profile;balance record;j jsonb:=to_jsonb(NEW);total numeric;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='外包资金原记录保留，不可删除';END IF;
 IF TG_TABLE_NAME='ty_wf_advance'THEN
  SELECT*INTO b FROM public.ty_wf_bank_receipt WHERE id=NEW.bank_receipt_id FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM public.ty_outsource_supplier s JOIN public.ty_company c ON c.group_id=s.group_id WHERE s.id=NEW.supplier_id AND s.group_id=NEW.group_id AND s.currency_code=NEW.currency AND c.id=NEW.company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预付款实际主体和币种不符';END IF;
  IF TG_OP='INSERT'THEN IF NEW.status<>'pending'OR NEW.revision<>1 OR NEW.verified_by IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预付款须先登记待核事实';END IF;
  ELSE IF(j-ARRAY['status','revision','verified_by'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','verified_by'])OR OLD.status<>'pending'OR NEW.status NOT IN('verified','rejected')OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预付款原事实不改，只可独立核定一次';END IF;END IF;
  IF NEW.status='verified'AND(NEW.verified_by IS NULL OR public.fn_ty_hr_same_human(NEW.verified_by,NEW.created_by)OR b.id IS NULL OR b.status<>'verified'OR b.kind<>'advance_out'OR b.group_id<>NEW.group_id OR b.company_id<>NEW.company_id OR b.supplier_id<>NEW.supplier_id OR b.currency<>NEW.currency OR b.amount<>NEW.amount OR EXISTS(SELECT 1 FROM public.ty_wf_advance WHERE id<>NEW.id AND bank_receipt_id=b.id AND status='verified'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核预付款须唯一对应真实独立核定的实际银行转出，不是新造资金';END IF;
  RETURN NEW;
 END IF;
 SELECT*INTO p FROM public.ty_wf_payable WHERE id=NEW.payable_id FOR UPDATE;SELECT*INTO r FROM public.ty_wf_bill_root WHERE id=p.root_id;
 IF p.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='真实已确认应付不存在';END IF;
 IF TG_TABLE_NAME='ty_wf_payment'THEN
  SELECT*INTO vp FROM public.ty_wf_vendor_profile WHERE id=NEW.bank_profile_id;
  IF vp.status<>'approved'OR vp.supplier_id<>r.supplier_id OR vp.group_id<>r.group_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款须使用同供应商已独立核定的收款版本';END IF;
  IF TG_OP='INSERT'THEN IF NEW.status<>'draft'OR NEW.revision<>1 OR NEW.approved_by IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款须先登记草稿，不能直接写已付';END IF;
  ELSE
   IF(j-ARRAY['status','revision','approved_by','approved_at','exported_by'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','approved_by','approved_at','exported_by'])OR NEW.revision<>OLD.revision+1 OR NOT(OLD.status='draft'AND NEW.status IN('approved','cancelled')OR OLD.status='approved'AND NEW.status IN('exported','cancelled')OR OLD.status='exported'AND NEW.status IN('submitted','unknown','succeeded','failed')OR OLD.status IN('submitted','unknown')AND NEW.status IN('unknown','succeeded','failed'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款只能依真实核准、导出、在途和银行结果推进';END IF;
  END IF;
  IF NEW.status IN('approved','exported')THEN
   SELECT*INTO balance FROM public.fn_ty_wf_ap_state(p.id,CASE WHEN TG_OP='UPDATE'AND OLD.status='approved'THEN NEW.id END);
   IF NEW.approved_by IS NULL OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by)OR NEW.payable_revision<>p.revision OR NEW.bank_profile_id<>(SELECT id FROM public.ty_wf_vendor_profile WHERE supplier_id=r.supplier_id AND status='approved'ORDER BY version DESC LIMIT 1)OR balance.opening_pending OR balance.available IS NULL OR NEW.amount>balance.available OR NEW.amount IS DISTINCT FROM(SELECT sum(amount)FROM public.ty_wf_payment_allocation WHERE payment_id=NEW.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款核准须当前应付/收款版本、独立人和全部用途分配，不得超过扣除已结与在途后的余额';END IF;
  END IF;
  IF NEW.status IN('submitted','unknown','succeeded','failed')AND NOT EXISTS(SELECT 1 FROM public.ty_wf_payment_event WHERE payment_id=NEW.id AND state=NEW.status)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款结果必须有原始追加事件，未知不可清空';END IF;
 ELSE
  SELECT*INTO b FROM public.ty_wf_bank_receipt WHERE id=NEW.bank_receipt_id FOR UPDATE;
  IF NEW.kind IN('payment','refund')AND(b.id IS NULL OR b.status<>'verified'OR b.group_id<>r.group_id OR b.company_id<>r.company_id OR b.supplier_id<>r.supplier_id OR b.currency<>r.currency OR b.kind<>CASE NEW.kind WHEN'payment'THEN'payment_out'ELSE'supplier_refund_in'END)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='结算必须绑定同主体币种的已核实际银行事实';END IF;
  IF NEW.kind='payment'THEN
   IF NOT EXISTS(SELECT 1 FROM public.ty_wf_payment x WHERE x.id=NEW.payment_id AND x.payable_id=p.id AND x.amount=NEW.amount AND x.status IN('exported','submitted','unknown'))OR NOT EXISTS(SELECT 1 FROM public.ty_wf_payment_event x WHERE x.payment_id=NEW.payment_id AND x.state='succeeded'AND x.bank_receipt_id=b.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='实付必须来自该付款的实际已核成功事件，不是供应商确认';END IF;
  ELSIF NEW.kind='advance_application'THEN
   SELECT*INTO adv FROM public.ty_wf_advance WHERE id=NEW.advance_id FOR UPDATE;
   IF adv.status<>'verified'OR adv.group_id<>r.group_id OR adv.company_id<>r.company_id OR adv.supplier_id<>r.supplier_id OR adv.currency<>r.currency OR NEW.amount>adv.amount-(SELECT coalesce(sum(amount),0)FROM public.ty_wf_settlement WHERE advance_id=adv.id AND kind='advance_application')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预付款核销须同主体币种已核余额，不能重用';END IF;
   SELECT*INTO balance FROM public.fn_ty_wf_ap_state(p.id);IF balance.available IS NULL OR NEW.amount>balance.available THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预付核销不能超过当前应付余款';END IF;
  ELSIF NEW.kind='refund'THEN
   SELECT*INTO orig FROM public.ty_wf_settlement WHERE id=NEW.original_settlement_id FOR UPDATE;
   IF orig.id IS NULL OR orig.payable_id<>p.id OR orig.kind='refund'OR NEW.amount>orig.amount-(SELECT coalesce(sum(amount),0)FROM public.ty_wf_settlement WHERE original_settlement_id=orig.id AND kind='refund')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='供应商退款只能反向真实原已付/已核销金额，累计不得超原款';END IF;
  END IF;
  IF b.id IS NOT NULL AND NEW.amount>b.amount-(SELECT coalesce(sum(amount),0)FROM public.ty_wf_settlement WHERE bank_receipt_id=b.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一银行事实不能被多个应付/退款重复消耗';END IF;
 END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_advance_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_advance FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_finance_guard();
CREATE TRIGGER ty_wf_payment_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_payment FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_finance_guard();
CREATE TRIGGER ty_wf_settlement_scope BEFORE INSERT ON ty_wf_settlement FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_finance_guard();
CREATE FUNCTION fn_ty_wf_allocation_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_wf_payment;s public.ty_wf_settlement;ap public.ty_wf_payable;l public.ty_wf_bill_line;r public.ty_wf_personal_receipt;original_amount numeric;used numeric;
BEGIN
 IF TG_TABLE_NAME='ty_wf_payment_allocation'THEN SELECT*INTO p FROM public.ty_wf_payment WHERE id=NEW.payment_id FOR UPDATE;IF p.status<>'draft'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款用途只在草稿完整登记，不可后换用途';END IF;SELECT*INTO ap FROM public.ty_wf_payable WHERE id=p.payable_id;
 ELSE SELECT*INTO s FROM public.ty_wf_settlement WHERE id=NEW.settlement_id FOR UPDATE;SELECT*INTO ap FROM public.ty_wf_payable WHERE id=s.payable_id;END IF;
 SELECT*INTO l FROM public.ty_wf_bill_line WHERE id=NEW.bill_line_id;
 IF l.version_id<>ap.last_version_id OR l.payable_effect<>'additive'OR l.amount<=0 OR NEW.amount>l.amount OR NEW.personal_instruction_id IS DISTINCT FROM l.personal_instruction_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款/核销分配必须沿同一已确认费用与真实个人资金用途';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_payment_allocation_guard BEFORE INSERT ON ty_wf_payment_allocation FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_allocation_guard();
CREATE TRIGGER ty_wf_settlement_allocation_guard BEFORE INSERT ON ty_wf_settlement_allocation FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_allocation_guard();
CREATE TRIGGER ty_wf_payment_allocation_keep BEFORE UPDATE OR DELETE ON ty_wf_payment_allocation FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_append_only();
CREATE FUNCTION fn_ty_wf_allocation_total()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE paymentkey bigint;settlementkey bigint;expected numeric;actual numeric;
BEGIN
 IF TG_TABLE_NAME='ty_wf_payment'THEN paymentkey:=NEW.id;
 ELSIF TG_TABLE_NAME='ty_wf_payment_allocation'THEN paymentkey:=NEW.payment_id;
 ELSIF TG_TABLE_NAME='ty_wf_settlement'THEN IF NEW.kind<>'advance_application'THEN RETURN NULL;END IF;settlementkey:=NEW.id;
 ELSE settlementkey:=NEW.settlement_id;END IF;
 IF paymentkey IS NOT NULL THEN SELECT amount INTO expected FROM public.ty_wf_payment WHERE id=paymentkey;SELECT coalesce(sum(amount),0)INTO actual FROM public.ty_wf_payment_allocation WHERE payment_id=paymentkey;
 ELSE SELECT amount INTO expected FROM public.ty_wf_settlement WHERE id=settlementkey;SELECT coalesce(sum(amount),0)INTO actual FROM public.ty_wf_settlement_allocation WHERE settlement_id=settlementkey;END IF;
 IF expected IS DISTINCT FROM actual THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款或预付核销总额必须与逐项用途分配完全守恒';END IF;RETURN NULL;
END;$$;
CREATE CONSTRAINT TRIGGER ty_wf_payment_total AFTER INSERT OR UPDATE ON ty_wf_payment DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_allocation_total();
CREATE CONSTRAINT TRIGGER ty_wf_payment_allocation_total AFTER INSERT ON ty_wf_payment_allocation DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_allocation_total();
CREATE CONSTRAINT TRIGGER ty_wf_settlement_total AFTER INSERT ON ty_wf_settlement DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_allocation_total();
CREATE CONSTRAINT TRIGGER ty_wf_settlement_allocation_total AFTER INSERT ON ty_wf_settlement_allocation DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_allocation_total();
CREATE FUNCTION fn_ty_wf_receipt_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE i public.ty_wf_personal_instruction;o public.ty_wf_personal_receipt;b public.ty_wf_bank_receipt;j jsonb:=to_jsonb(NEW);ok boolean;used numeric;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人到账与退还原回执保留，不可删除';END IF;
 SELECT*INTO i FROM public.ty_wf_personal_instruction WHERE id=NEW.instruction_id FOR UPDATE;
 IF NEW.group_id<>i.group_id OR NEW.currency<>i.currency THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人回执须对应原指令集团和币种';END IF;
 IF TG_OP='INSERT'THEN IF NEW.status<>'draft'OR NEW.revision<>1 OR NEW.reviewed_by IS NOT NULL OR NEW.applied_by IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人执行结果先登记待核原事实，不可预造已到账';END IF;
 ELSE IF(j-ARRAY['status','revision','reviewed_by','reviewed_at','review_ref','applied_by','applied_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','reviewed_by','reviewed_at','review_ref','applied_by','applied_at'])OR NEW.revision<>OLD.revision+1 OR NOT(OLD.status='draft'AND NEW.status IN('reviewed','rejected')OR OLD.status='reviewed'AND NEW.status='applied')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核个人回执不可覆写，须受控追加反向事实';END IF;END IF;
 IF NEW.status IN('reviewed','applied')THEN
  IF NEW.reviewed_by IS NULL OR public.fn_ty_hr_same_human(NEW.reviewed_by,NEW.recorded_by)OR public.fn_ty_hr_actor_is_person(NEW.reviewed_by,i.group_id,i.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人回执须不同自然人且非受益人复核';END IF;
  IF NEW.effect IN('refund_to_employer','refund_to_supplier','custody_return_to_employer')THEN
   SELECT*INTO o FROM public.ty_wf_personal_receipt WHERE id=NEW.original_receipt_id FOR UPDATE;
   IF o.instruction_id<>i.id OR o.status<>'applied'OR o.effect<>(CASE WHEN NEW.effect='custody_return_to_employer'THEN'failed'ELSE'success'END)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='返还只能承接原已核已采用成功或未执行事实，不能造负已结';END IF;
   SELECT coalesce(sum(amount),0)INTO used FROM public.ty_wf_personal_receipt WHERE original_receipt_id=o.id AND id<>NEW.id AND status IN('reviewed','applied');IF used+NEW.amount>o.amount THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='累计退款不得超过原真实已付/未执行金额';END IF;
  END IF;
  IF NEW.effect IN('refund_to_employer','custody_return_to_employer')THEN
   SELECT*INTO b FROM public.ty_wf_bank_receipt WHERE id=NEW.bank_receipt_id FOR UPDATE;
   IF b.id IS NULL OR b.status<>'verified'OR b.kind<>'supplier_refund_in'OR b.group_id<>i.group_id OR b.company_id<>i.company_id OR b.supplier_id<>i.supplier_id OR b.currency<>i.currency THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='返雇主须真实独立已核银行返款，失败本身不能释放供应商已持有资金';END IF;
   SELECT coalesce(sum(amount),0)INTO used FROM public.ty_wf_personal_receipt WHERE bank_receipt_id=b.id AND id<>NEW.id AND status IN('reviewed','applied')AND effect IN('refund_to_employer','custody_return_to_employer');IF used+NEW.amount>b.amount THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人资金返还各人合计不得重复消耗同一实际银行返款';END IF;
  END IF;
 END IF;
 IF NEW.status='applied'THEN
  IF public.fn_ty_hr_actor_is_person(NEW.applied_by,i.group_id,i.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人资金结果不得由受益人本人执行采用';END IF;
  IF NEW.effect IN('refund_to_employer','custody_return_to_employer')AND NEW.amount IS DISTINCT FROM(SELECT sum(amount)FROM public.ty_wf_fund_return_link WHERE personal_receipt_id=NEW.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='返雇主须同事务完成同源AP退款，不可单独释放个人资金';END IF;
  IF to_regprocedure('public.fn_ty_pay_agency_receipt_applied(bigint)')IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='统一员工资金桥缺失，不得伪造已采用';END IF;
  EXECUTE'SELECT public.fn_ty_pay_agency_receipt_applied($1)'INTO ok USING NEW.id;IF NOT coalesce(ok,false)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人回执未在统一资金父账真实采用';END IF;
 END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_personal_receipt_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_personal_receipt FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_receipt_guard();
CREATE FUNCTION fn_ty_wf_payment_event_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_wf_payment;r public.ty_wf_bill_root;b public.ty_wf_bank_receipt;
BEGIN
 SELECT*INTO p FROM public.ty_wf_payment WHERE id=NEW.payment_id FOR UPDATE;SELECT br.*INTO r FROM public.ty_wf_payable ap JOIN public.ty_wf_bill_root br ON br.id=ap.root_id WHERE ap.id=p.payable_id;
 IF p.status NOT IN('exported','submitted','unknown')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原付款未进入真实执行阶段，不能预造银行事件';END IF;
 IF NEW.state IN('succeeded','failed')THEN
  SELECT*INTO b FROM public.ty_wf_bank_receipt WHERE id=NEW.bank_receipt_id FOR UPDATE;
  IF b.id IS NULL OR b.status<>'verified'OR b.kind<>(CASE NEW.state WHEN'succeeded'THEN'payment_out'ELSE'transfer_not_executed'END)OR b.amount<>p.amount OR b.group_id<>r.group_id OR b.company_id<>r.company_id OR b.supplier_id<>r.supplier_id OR b.currency<>r.currency THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成功或未执行必须有同主体币种金额的实际已核银行证据';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_payment_event_guard BEFORE INSERT ON ty_wf_payment_event FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_payment_event_guard();
CREATE FUNCTION fn_ty_wf_return_link_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_wf_personal_receipt;i public.ty_wf_personal_instruction;s public.ty_wf_settlement;originalkey bigint;allocation_amount numeric;allocation_instruction bigint;returned numeric;
BEGIN
 SELECT*INTO r FROM public.ty_wf_personal_receipt WHERE id=NEW.personal_receipt_id FOR UPDATE;SELECT*INTO i FROM public.ty_wf_personal_instruction WHERE id=r.instruction_id;SELECT*INTO s FROM public.ty_wf_settlement WHERE id=NEW.settlement_id;
 IF NEW.payment_allocation_id IS NOT NULL THEN SELECT a.amount,a.personal_instruction_id,st.id INTO allocation_amount,allocation_instruction,originalkey FROM public.ty_wf_payment_allocation a JOIN public.ty_wf_payment p ON p.id=a.payment_id JOIN public.ty_wf_settlement st ON st.payment_id=p.id AND st.kind='payment'WHERE a.id=NEW.payment_allocation_id AND p.status='succeeded';SELECT coalesce(sum(amount),0)INTO returned FROM public.ty_wf_fund_return_link WHERE payment_allocation_id=NEW.payment_allocation_id;
 ELSE SELECT a.amount,a.personal_instruction_id,st.id INTO allocation_amount,allocation_instruction,originalkey FROM public.ty_wf_settlement_allocation a JOIN public.ty_wf_settlement st ON st.id=a.settlement_id JOIN public.ty_wf_advance ad ON ad.id=st.advance_id WHERE a.id=NEW.advance_allocation_id AND st.kind='advance_application'AND ad.status='verified';SELECT coalesce(sum(amount),0)INTO returned FROM public.ty_wf_fund_return_link WHERE advance_allocation_id=NEW.advance_allocation_id;END IF;
 IF r.id IS NULL OR r.status NOT IN('reviewed','applied')OR r.effect NOT IN('refund_to_employer','custody_return_to_employer')OR allocation_instruction IS DISTINCT FROM i.id OR originalkey IS NULL OR s.kind<>'refund'OR s.original_settlement_id<>originalkey OR s.bank_receipt_id IS DISTINCT FROM r.bank_receipt_id OR s.amount<>NEW.amount OR returned+NEW.amount>allocation_amount THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人返款与原实际供应商收款、同一银行事实及AP反向份额须逐项守恒';END IF;
 IF NEW.amount+(SELECT coalesce(sum(amount),0)FROM public.ty_wf_fund_return_link WHERE personal_receipt_id=r.id)>r.amount THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人实际返款不能在多个原收款分配中重复使用';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_fund_return_scope BEFORE INSERT ON ty_wf_fund_return_link FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_return_link_guard();
CREATE FUNCTION fn_ty_wf_invoice_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE i public.ty_wf_invoice;o public.ty_wf_invoice;p public.ty_wf_payable;r public.ty_wf_bill_root;used numeric;cap numeric;
BEGIN
 IF TG_TABLE_NAME='ty_wf_invoice'THEN
  IF NOT EXISTS(SELECT 1 FROM public.ty_outsource_supplier s JOIN public.ty_company c ON c.group_id=s.group_id WHERE s.id=NEW.supplier_id AND s.group_id=NEW.group_id AND s.currency_code=NEW.currency AND c.id=NEW.company_id)OR NEW.verification_state<>'manually_registered'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='票据须对应实际主体币种；人工登记不能冒称外部税务查验';END IF;
  IF NEW.kind='invoice'AND(NEW.net<0 OR NEW.tax<0 OR NEW.gross<=0)OR NEW.kind='credit_note'AND(NEW.net>0 OR NEW.tax>0 OR NEW.gross>=0)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='正票、红字金额符号必须明确';END IF;
  IF NEW.kind='credit_note'THEN SELECT*INTO o FROM public.ty_wf_invoice WHERE id=NEW.original_invoice_id FOR UPDATE;IF o.kind<>'invoice'OR o.group_id<>NEW.group_id OR o.company_id<>NEW.company_id OR o.supplier_id<>NEW.supplier_id OR o.currency<>NEW.currency OR -NEW.gross>o.gross+(SELECT coalesce(sum(gross),0)FROM public.ty_wf_invoice WHERE original_invoice_id=o.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='红字须对应同主体原票且累计不得超过原票';END IF;END IF;
 ELSE
  SELECT*INTO i FROM public.ty_wf_invoice WHERE id=NEW.invoice_id FOR UPDATE;SELECT*INTO p FROM public.ty_wf_payable WHERE id=NEW.payable_id FOR UPDATE;SELECT*INTO r FROM public.ty_wf_bill_root WHERE id=p.root_id;
  SELECT coalesce(sum(amount),0)INTO used FROM public.ty_wf_invoice_allocation WHERE invoice_id=i.id;
  IF i.group_id<>r.group_id OR i.company_id<>r.company_id OR i.supplier_id<>r.supplier_id OR i.currency<>r.currency OR sign(NEW.amount)<>sign(i.gross)OR abs(used+NEW.amount)>abs(i.gross)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='票据分配须同实际主体币种，金额不得超票面或反向';END IF;
  SELECT coalesce(sum(l.amount),0)INTO cap FROM public.ty_wf_bill_line l WHERE l.version_id=p.last_version_id AND l.purpose IN('service_fee','adjustment')AND l.payable_effect='additive';
  SELECT coalesce(sum(amount),0)INTO used FROM public.ty_wf_invoice_allocation WHERE payable_id=p.id;
  IF used+NEW.amount<0 OR used+NEW.amount>greatest(0,cap)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='票据只覆盖真实费用，不给净工资和代缴资金重复开费用票';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_invoice_scope BEFORE INSERT ON ty_wf_invoice FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_invoice_guard();
CREATE TRIGGER ty_wf_invoice_allocation_scope BEFORE INSERT ON ty_wf_invoice_allocation FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_invoice_guard();
CREATE FUNCTION fn_ty_wf_opening_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_wf_bill_root;j jsonb:=to_jsonb(NEW);
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='历史往来资金期初保留核定记录';END IF;
 SELECT*INTO r FROM public.ty_wf_bill_root WHERE id=NEW.root_id FOR UPDATE;
 IF TG_OP='INSERT'THEN IF r.opening_status<>'pending'OR NEW.status<>'pending'OR NEW.verified_by IS NOT NULL OR NEW.revision<>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='只有历史待核根可登记新的待核期初';END IF;
 ELSE IF(j-ARRAY['status','revision','verified_by','review_ref'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','verified_by','review_ref'])OR OLD.status<>'pending'OR NEW.status NOT IN('verified','rejected')OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='历史资金期初原事实不可改写';END IF;END IF;
 IF NEW.status='verified'AND(NEW.verified_by IS NULL OR public.fn_ty_hr_same_human(NEW.verified_by,NEW.created_by)OR EXISTS(SELECT 1 FROM public.ty_wf_ap_entry x JOIN public.ty_wf_payable p ON p.id=x.payable_id WHERE p.root_id=r.id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='期初须独立核定且先于新应付确认，不能覆盖已记账';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_opening_scope BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_opening FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_opening_guard();
CREATE FUNCTION fn_ty_wf_line_available(p_line bigint,p_exclude_payment bigint DEFAULT NULL)RETURNS numeric LANGUAGE sql STABLE SET search_path=''AS $$
 WITH x AS(SELECT l.economic_key,v.root_id FROM public.ty_wf_bill_line l JOIN public.ty_wf_bill_version v ON v.id=l.version_id WHERE l.id=p_line),target AS(SELECT coalesce(sum(l.amount),0)n FROM x JOIN public.ty_wf_payable ap ON ap.root_id=x.root_id JOIN public.ty_wf_bill_line l ON l.version_id=ap.last_version_id AND l.economic_key=x.economic_key WHERE l.payable_effect='additive'),payments AS(SELECT coalesce(sum(a.amount),0)n FROM x JOIN public.ty_wf_bill_version v ON v.root_id=x.root_id JOIN public.ty_wf_bill_line l ON l.version_id=v.id AND l.economic_key=x.economic_key JOIN public.ty_wf_payment_allocation a ON a.bill_line_id=l.id JOIN public.ty_wf_payment p ON p.id=a.payment_id WHERE p.status IN('approved','exported','submitted','unknown','succeeded')AND(p.id IS DISTINCT FROM p_exclude_payment OR p.status='succeeded')),prepay AS(SELECT coalesce(sum(a.amount),0)n FROM x JOIN public.ty_wf_bill_version v ON v.root_id=x.root_id JOIN public.ty_wf_bill_line l ON l.version_id=v.id AND l.economic_key=x.economic_key JOIN public.ty_wf_settlement_allocation a ON a.bill_line_id=l.id JOIN public.ty_wf_settlement s ON s.id=a.settlement_id WHERE s.kind='advance_application'),returns AS(SELECT coalesce(sum(z.amount),0)n FROM(SELECT DISTINCT f.id,f.amount FROM x JOIN public.ty_wf_bill_version v ON v.root_id=x.root_id JOIN public.ty_wf_bill_line l ON l.version_id=v.id AND l.economic_key=x.economic_key JOIN public.ty_wf_payment_allocation pa ON pa.bill_line_id=l.id JOIN public.ty_wf_fund_return_link f ON f.payment_allocation_id=pa.id UNION SELECT DISTINCT f.id,f.amount FROM x JOIN public.ty_wf_bill_version v ON v.root_id=x.root_id JOIN public.ty_wf_bill_line l ON l.version_id=v.id AND l.economic_key=x.economic_key JOIN public.ty_wf_settlement_allocation aa ON aa.bill_line_id=l.id JOIN public.ty_wf_fund_return_link f ON f.advance_allocation_id=aa.id)z),otherreturns AS(SELECT coalesce(sum(a.amount),0)n FROM x JOIN public.ty_wf_bill_version v ON v.root_id=x.root_id JOIN public.ty_wf_bill_line l ON l.version_id=v.id AND l.economic_key=x.economic_key JOIN public.ty_wf_settlement_allocation a ON a.bill_line_id=l.id JOIN public.ty_wf_settlement s ON s.id=a.settlement_id WHERE s.kind='refund')
 SELECT greatest(0,target.n-payments.n-prepay.n+returns.n+otherreturns.n)FROM target,payments,prepay,returns,otherreturns;
$$;
CREATE FUNCTION fn_ty_wf_payment_conservation()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE k bigint;p public.ty_wf_payment;n numeric;
BEGIN
 IF TG_TABLE_NAME='ty_wf_payment'THEN k:=NEW.id;ELSE IF NEW.payment_id IS NULL THEN RETURN NULL;END IF;k:=NEW.payment_id;END IF;
 SELECT*INTO p FROM public.ty_wf_payment WHERE id=k;SELECT coalesce(sum(amount),0)INTO n FROM public.ty_wf_settlement WHERE payment_id=k AND kind='payment';
 IF p.status='succeeded'AND n<>p.amount OR p.status<>'succeeded'AND n<>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='银行成功状态必须与同一付款真实结算完全守恒，不能跳过资金账';END IF;RETURN NULL;
END;$$;
CREATE CONSTRAINT TRIGGER ty_wf_payment_bank_conservation AFTER INSERT OR UPDATE ON ty_wf_payment DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_payment_conservation();
CREATE CONSTRAINT TRIGGER ty_wf_settlement_bank_conservation AFTER INSERT ON ty_wf_settlement DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_payment_conservation();
CREATE FUNCTION fn_ty_wf_purpose_budget_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE a record;v numeric;state jsonb;hasbridge boolean;parentkey bigint;instructionkey bigint;
BEGIN
 IF TG_TABLE_NAME='ty_wf_payment'THEN
  IF NEW.status NOT IN('approved','exported')THEN RETURN NEW;END IF;
  FOR a IN SELECT l.economic_key,min(l.id)line_id,sum(pa.amount)amount FROM public.ty_wf_payment_allocation pa JOIN public.ty_wf_bill_line l ON l.id=pa.bill_line_id WHERE pa.payment_id=NEW.id GROUP BY l.economic_key LOOP
   v:=public.fn_ty_wf_line_available(a.line_id,NEW.id);IF a.amount>v THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一费用用途跨付款累计不得超当前目标，不能借另一用途余额支付';END IF;
  END LOOP;
  FOR instructionkey IN SELECT DISTINCT personal_instruction_id FROM public.ty_wf_payment_allocation WHERE payment_id=NEW.id AND personal_instruction_id IS NOT NULL ORDER BY personal_instruction_id LOOP
   IF to_regprocedure('public.fn_ty_pay_agency_custody_state(bigint,bigint)')IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='统一员工代发资金未接通，不得批准供应商拨款';END IF;
   EXECUTE'SELECT public.fn_ty_pay_agency_custody_state($1,$2)'INTO state USING instructionkey,CASE WHEN OLD.status='approved'THEN NEW.id END;
   SELECT sum(amount)INTO v FROM public.ty_wf_payment_allocation WHERE payment_id=NEW.id AND personal_instruction_id=instructionkey;
   IF NOT coalesce((state->>'ready')::boolean,false)OR(state->>'available')IS NULL OR v>(state->>'available')::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='净工资代发资金缺当前已核可拨余额，不能耗用报销或重复工资';END IF;
  END LOOP;
 ELSE
  -- Prepayment application has already entered AP, so compare the purpose before this new allocation.
  SELECT public.fn_ty_wf_line_available(NEW.bill_line_id)INTO v;
  IF NEW.amount>v THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预付核销不能跨用途超支当前费用目标';END IF;
 END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_payment_purpose_budget BEFORE UPDATE ON ty_wf_payment FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_purpose_budget_guard();
CREATE TRIGGER ty_wf_advance_purpose_budget BEFORE INSERT ON ty_wf_settlement_allocation FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_purpose_budget_guard();
CREATE FUNCTION fn_ty_wf_mandate_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE c public.ty_outsource_contract;e public.ty_employment;j jsonb:=to_jsonb(NEW);
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='委托授权保留，撤销另留轨迹';END IF;
 SELECT*INTO c FROM public.ty_outsource_contract WHERE id=NEW.contract_id;SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
 IF c.service_kind<>'payroll_agency'OR c.group_id<>NEW.group_id OR c.supplier_id<>NEW.supplier_id OR e.group_id<>NEW.group_id OR e.person_id<>NEW.person_id OR e.company_id<>NEW.company_id OR e.employment_type='outsourced'OR NOT EXISTS(SELECT 1 FROM public.ty_outsource_contract_company WHERE contract_id=c.id AND company_id=NEW.company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='净工资委托须对应真实直营雇主关系与同一服务合同，不能冒造外包人员工资';END IF;
 IF TG_OP='INSERT'THEN IF NEW.status<>'pending'OR NEW.revision<>1 OR NEW.approved_by IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='实际委托先登记待核，不能预核准';END IF;
 ELSE IF(j-ARRAY['status','revision','approved_by','review_ref'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','approved_by','review_ref'])OR NEW.revision<>OLD.revision+1 OR NOT(OLD.status='pending'AND NEW.status IN('approved','rejected')OR OLD.status='approved'AND NEW.status='revoked')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原委托范围和期间不可覆写，只可受控核定或撤销';END IF;END IF;
 IF NEW.status='approved'AND(NEW.approved_by IS NULL OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by)OR public.fn_ty_hr_actor_is_person(NEW.approved_by,NEW.group_id,NEW.person_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='实际代发授权须独立且非受益人核准';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_mandate_scope BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_mandate FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_mandate_guard();
CREATE FUNCTION fn_ty_wf_instruction_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE m public.ty_wf_mandate;j jsonb:=to_jsonb(NEW);ok boolean;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='逐人资金指令保留原事实';END IF;
 SELECT*INTO m FROM public.ty_wf_mandate WHERE id=NEW.mandate_id;
 IF m.group_id<>NEW.group_id OR m.company_id<>NEW.company_id OR m.person_id<>NEW.person_id OR m.employment_id<>NEW.employment_id OR m.supplier_id<>NEW.supplier_id OR m.contract_id<>NEW.contract_id OR NEW.component<>'net_wage'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人净工资指令身份须与实际委托相同，不得跨主体或挪用报销';END IF;
 IF TG_OP='INSERT'THEN IF NEW.status<>'draft'OR NEW.revision<>1 OR NEW.approved_by IS NOT NULL OR NEW.executed_by IS NOT NULL OR NEW.fund_parent_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人指令须从真实来源草稿开始，不能预造占用或已付';END IF;
 ELSE
  IF(j-ARRAY['status','revision','approved_by','executed_by','fund_parent_id'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','approved_by','executed_by','fund_parent_id'])OR NEW.revision<>OLD.revision+1 OR OLD.fund_parent_id IS NOT NULL AND NEW.fund_parent_id IS DISTINCT FROM OLD.fund_parent_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原工资来源、金额、委托和共同资金根不可改换';END IF;
  IF OLD.status='draft'AND NEW.status NOT IN('approved','cancelled')OR OLD.status='approved'AND NEW.status NOT IN('reserved','cancelled')OR OLD.status='cancelled'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='个人指令须先核准再真实占用，已取消不复活';END IF;
 END IF;
 IF NEW.status='approved'AND(m.status<>'approved'OR NEW.approved_by IS NULL OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.created_by)OR public.fn_ty_hr_actor_is_person(NEW.approved_by,NEW.group_id,NEW.person_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='净工资指令须实际有效委托、独立非受益人核准';END IF;
 IF NEW.status IN('reserved','submitted','unknown','partially_settled','settled','failed')THEN
  IF NEW.executed_by IS NULL OR public.fn_ty_hr_actor_is_person(NEW.executed_by,NEW.group_id,NEW.person_id)OR to_regprocedure('public.fn_ty_pay_agency_instruction_matches(bigint,bigint)')IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='共同员工资金桥缺失或本人执行，不得虚造占用/已付';END IF;
  EXECUTE'SELECT public.fn_ty_pay_agency_instruction_matches($1,$2)'INTO ok USING NEW.id,NEW.fund_parent_id;IF NOT coalesce(ok,false)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='指令未在统一真实工资父账正确占用';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_instruction_scope BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_personal_instruction FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_instruction_guard();

ALTER TABLE ty_wf_file ADD COLUMN visibility text NOT NULL DEFAULT'internal'CHECK(visibility IN('shared','hr_vendor','internal'));

ALTER TABLE ty_wf_file ALTER COLUMN company_id DROP NOT NULL;
CREATE FUNCTION fn_ty_wf_file_scope()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE gid bigint;cid bigint;sid bigint;
BEGIN
 CASE NEW.owner_kind
 WHEN'vendor_profile'THEN SELECT group_id,company_id,supplier_id INTO gid,cid,sid FROM public.ty_wf_vendor_profile WHERE id=NEW.owner_id;
 WHEN'price'THEN SELECT x.group_id,x.company_id,c.supplier_id INTO gid,cid,sid FROM public.ty_wf_price x JOIN public.ty_outsource_contract c ON c.id=x.contract_id WHERE x.id=NEW.owner_id;
 WHEN'order'THEN SELECT x.group_id,x.company_id,c.supplier_id INTO gid,cid,sid FROM public.ty_wf_order x JOIN public.ty_outsource_contract c ON c.id=x.contract_id WHERE x.id=NEW.owner_id;
 WHEN'bill'THEN SELECT r.group_id,r.company_id,r.supplier_id INTO gid,cid,sid FROM public.ty_wf_bill_version v JOIN public.ty_wf_bill_root r ON r.id=v.root_id WHERE v.id=NEW.owner_id;
 WHEN'invoice'THEN SELECT group_id,company_id,supplier_id INTO gid,cid,sid FROM public.ty_wf_invoice WHERE id=NEW.owner_id;
 WHEN'payment'THEN SELECT r.group_id,r.company_id,r.supplier_id INTO gid,cid,sid FROM public.ty_wf_payment p JOIN public.ty_wf_payable a ON a.id=p.payable_id JOIN public.ty_wf_bill_root r ON r.id=a.root_id WHERE p.id=NEW.owner_id;
 WHEN'mandate'THEN SELECT group_id,company_id,supplier_id INTO gid,cid,sid FROM public.ty_wf_mandate WHERE id=NEW.owner_id;
 WHEN'thread'THEN SELECT c.group_id,ctx.company_id,c.supplier_id INTO gid,cid,sid FROM public.ty_outsource_thread th JOIN public.ty_outsource_contract c ON c.id=th.contract_id JOIN public.ty_wf_thread_context ctx ON ctx.thread_id=th.id WHERE th.id=NEW.owner_id;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='附件对象类型未接入';END CASE;
 IF gid IS NULL OR gid<>NEW.group_id OR cid IS DISTINCT FROM NEW.company_id OR sid<>NEW.supplier_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='附件必须归属真实同集团公司和供应商原对象，不接受任意文件路径或换属';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_file_scope BEFORE INSERT ON ty_wf_file FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_file_scope();

CREATE FUNCTION fn_ty_wf_allocation_scope()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE v public.ty_wf_acceptance_version;r public.ty_wf_acceptance_root;
BEGIN
 IF TG_OP<>'INSERT'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务分摊保留原版本，不可覆写';END IF;
 SELECT*INTO v FROM public.ty_wf_acceptance_version WHERE id=NEW.acceptance_version_id FOR UPDATE;SELECT*INTO r FROM public.ty_wf_acceptance_root WHERE id=v.root_id;
 IF v.status<>'draft'OR NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.work_company_id AND group_id=r.group_id)OR NEW.coverage_from<coalesce(v.coverage_from,r.work_date)OR NEW.coverage_to>coalesce(v.coverage_to,r.slice_end,r.work_date+1)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工作地分摊须属于同一真实人员月、实际公司和来源覆盖期草稿';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_acceptance_allocation_scope BEFORE INSERT OR UPDATE OR DELETE ON ty_wf_acceptance_allocation FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_allocation_scope();
CREATE FUNCTION fn_ty_wf_allocation_approved_total()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE k bigint;v public.ty_wf_acceptance_version;total numeric;
BEGIN
 IF TG_TABLE_NAME='ty_wf_acceptance_version'THEN k:=NEW.id;ELSE k:=NEW.acceptance_version_id;END IF;SELECT*INTO v FROM public.ty_wf_acceptance_version WHERE id=k;
 IF v.status='approved'THEN SELECT sum(quantity)INTO total FROM public.ty_wf_acceptance_allocation WHERE acceptance_version_id=k;IF total IS DISTINCT FROM v.accepted_quantity THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工作地分摊合计必须等于唯一人员月份服务总量，接收视图不能新增数量';END IF;END IF;RETURN NULL;
END;$$;
CREATE CONSTRAINT TRIGGER ty_wf_acceptance_allocation_total AFTER INSERT OR UPDATE ON ty_wf_acceptance_version DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_allocation_approved_total();
CREATE CONSTRAINT TRIGGER ty_wf_acceptance_child_total AFTER INSERT ON ty_wf_acceptance_allocation DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_allocation_approved_total();
ALTER TABLE ty_wf_settlement_allocation ADD COLUMN original_payment_allocation_id bigint REFERENCES ty_wf_payment_allocation(id);
ALTER TABLE ty_wf_settlement_allocation ADD COLUMN original_advance_allocation_id bigint REFERENCES ty_wf_settlement_allocation(id);
CREATE OR REPLACE FUNCTION fn_ty_wf_allocation_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_wf_payment;s public.ty_wf_settlement;ap public.ty_wf_payable;l public.ty_wf_bill_line;original_line bigint;original_settlement bigint;original_amount numeric;used numeric;
BEGIN
 IF TG_TABLE_NAME='ty_wf_payment_allocation'THEN SELECT*INTO p FROM public.ty_wf_payment WHERE id=NEW.payment_id FOR UPDATE;IF p.status<>'draft'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款用途只在草稿完整登记，不可后换用途';END IF;SELECT*INTO ap FROM public.ty_wf_payable WHERE id=p.payable_id;
 ELSE SELECT*INTO s FROM public.ty_wf_settlement WHERE id=NEW.settlement_id FOR UPDATE;SELECT*INTO ap FROM public.ty_wf_payable WHERE id=s.payable_id;END IF;
 SELECT*INTO l FROM public.ty_wf_bill_line WHERE id=NEW.bill_line_id;
 IF TG_TABLE_NAME='ty_wf_settlement_allocation'AND s.kind='refund'THEN
  IF num_nonnulls(NEW.original_payment_allocation_id,NEW.original_advance_allocation_id)<>1 OR NEW.personal_instruction_id IS NOT NULL OR l.personal_instruction_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务退款须绑定原实际付款份额；员工资金另走同源逐人回执';END IF;
  IF NEW.original_payment_allocation_id IS NOT NULL THEN SELECT a.bill_line_id,a.amount,st.id INTO original_line,original_amount,original_settlement FROM public.ty_wf_payment_allocation a JOIN public.ty_wf_payment pm ON pm.id=a.payment_id JOIN public.ty_wf_settlement st ON st.payment_id=pm.id AND st.kind='payment'WHERE a.id=NEW.original_payment_allocation_id AND pm.status='succeeded';SELECT coalesce(sum(amount),0)INTO used FROM public.ty_wf_settlement_allocation WHERE original_payment_allocation_id=NEW.original_payment_allocation_id;
  ELSE SELECT a.bill_line_id,a.amount,st.id INTO original_line,original_amount,original_settlement FROM public.ty_wf_settlement_allocation a JOIN public.ty_wf_settlement st ON st.id=a.settlement_id WHERE a.id=NEW.original_advance_allocation_id AND st.kind='advance_application';SELECT coalesce(sum(amount),0)INTO used FROM public.ty_wf_settlement_allocation WHERE original_advance_allocation_id=NEW.original_advance_allocation_id;END IF;
  IF original_settlement IS NULL OR original_settlement<>s.original_settlement_id OR original_line<>NEW.bill_line_id OR NEW.amount+used>original_amount THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='服务退款的原收款、用途和累计退还必须逐项守恒，不以当前低目标限制实际退款';END IF;
 ELSE
  IF l.version_id<>ap.last_version_id OR l.payable_effect<>'additive'OR l.amount<=0 OR NEW.amount>l.amount OR NEW.personal_instruction_id IS DISTINCT FROM l.personal_instruction_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款/核销分配必须沿同一已确认费用与真实个人资金用途';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE OR REPLACE FUNCTION fn_ty_wf_allocation_total()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE paymentkey bigint;settlementkey bigint;expected numeric;actual numeric;kind text;
BEGIN
 IF TG_TABLE_NAME='ty_wf_payment'THEN paymentkey:=NEW.id;ELSIF TG_TABLE_NAME='ty_wf_payment_allocation'THEN paymentkey:=NEW.payment_id;ELSIF TG_TABLE_NAME='ty_wf_settlement'THEN IF NEW.kind='payment'THEN RETURN NULL;END IF;settlementkey:=NEW.id;ELSE settlementkey:=NEW.settlement_id;END IF;
 IF paymentkey IS NOT NULL THEN SELECT amount INTO expected FROM public.ty_wf_payment WHERE id=paymentkey;SELECT coalesce(sum(amount),0)INTO actual FROM public.ty_wf_payment_allocation WHERE payment_id=paymentkey;
 ELSE SELECT amount,s.kind INTO expected,kind FROM public.ty_wf_settlement s WHERE id=settlementkey;SELECT coalesce(sum(amount),0)INTO actual FROM public.ty_wf_settlement_allocation WHERE settlement_id=settlementkey;IF kind='refund'THEN actual:=actual+(SELECT coalesce(sum(amount),0)FROM public.ty_wf_fund_return_link WHERE settlement_id=settlementkey);END IF;END IF;
 IF expected IS DISTINCT FROM actual THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款、核销或退款总额必须与原始用途分配完全守恒';END IF;RETURN NULL;
END;$$;
CREATE CONSTRAINT TRIGGER ty_wf_return_link_total AFTER INSERT ON ty_wf_fund_return_link DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_allocation_total();
CREATE OR REPLACE FUNCTION fn_ty_wf_purpose_budget_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE a record;v numeric;state jsonb;instructionkey bigint;s public.ty_wf_settlement;
BEGIN
 IF TG_TABLE_NAME='ty_wf_payment'THEN
  IF NEW.status NOT IN('approved','exported')THEN RETURN NEW;END IF;
  FOR a IN SELECT l.economic_key,min(l.id)line_id,sum(pa.amount)amount FROM public.ty_wf_payment_allocation pa JOIN public.ty_wf_bill_line l ON l.id=pa.bill_line_id WHERE pa.payment_id=NEW.id GROUP BY l.economic_key LOOP v:=public.fn_ty_wf_line_available(a.line_id,NEW.id);IF a.amount>v THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一费用用途跨付款累计不得超当前目标，不能借另一用途余额支付';END IF;END LOOP;
  FOR instructionkey IN SELECT DISTINCT personal_instruction_id FROM public.ty_wf_payment_allocation WHERE payment_id=NEW.id AND personal_instruction_id IS NOT NULL ORDER BY personal_instruction_id LOOP
   IF to_regprocedure('public.fn_ty_pay_agency_custody_state(bigint,bigint)')IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='统一员工代发资金未接通，不得批准供应商拨款';END IF;
   EXECUTE'SELECT public.fn_ty_pay_agency_custody_state($1,$2)'INTO state USING instructionkey,CASE WHEN OLD.status='approved'THEN NEW.id END;SELECT sum(amount)INTO v FROM public.ty_wf_payment_allocation WHERE payment_id=NEW.id AND personal_instruction_id=instructionkey;IF NOT coalesce((state->>'ready')::boolean,false)OR(state->>'available')IS NULL OR v>(state->>'available')::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='净工资代发资金缺当前已核可拨余额，不能耗用报销或重复工资';END IF;
  END LOOP;
 ELSE
  SELECT*INTO s FROM public.ty_wf_settlement WHERE id=NEW.settlement_id;IF s.kind='refund'THEN RETURN NEW;END IF;
  SELECT public.fn_ty_wf_line_available(NEW.bill_line_id)INTO v;IF NEW.amount>v THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='预付核销不能跨用途超支当前费用目标';END IF;
 END IF;RETURN NEW;
END;$$;

-- A pre-export cancellation releases only the payment hold, never the AP debt or employee cash obligation.
CREATE TABLE ty_wf_payment_cancellation(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,payment_id bigint NOT NULL UNIQUE REFERENCES ty_wf_payment(id),kind text NOT NULL CHECK(kind IN('withdrawn','review_rejected')),reason text NOT NULL CHECK(length(reason)>=4),recorded_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TRIGGER ty_wf_cancel_immutable BEFORE UPDATE OR DELETE ON ty_wf_payment_cancellation FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_append_only();
CREATE FUNCTION fn_ty_wf_cancel_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_wf_payment;
BEGIN
 IF TG_TABLE_NAME='ty_wf_payment_cancellation'THEN SELECT*INTO p FROM public.ty_wf_payment WHERE id=NEW.payment_id FOR UPDATE;IF p.status NOT IN('draft','approved')OR NEW.kind='review_rejected'AND(p.status<>'draft'OR public.fn_ty_hr_same_human(NEW.recorded_by,p.created_by))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款撤回仅限尚未导出，独立否决须真实复核人';END IF;
 ELSE IF NEW.status='cancelled'AND NOT EXISTS(SELECT 1 FROM public.ty_wf_payment_cancellation WHERE payment_id=NEW.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='付款取消须保留真实撤回或独立不予核准记录';END IF;END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_wf_cancel_insert BEFORE INSERT ON ty_wf_payment_cancellation FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_cancel_guard();
CREATE CONSTRAINT TRIGGER ty_wf_cancel_proof AFTER INSERT OR UPDATE ON ty_wf_payment DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_cancel_guard();

-- A native contract's sealed source is not editable through legacy209 parent tables.
CREATE FUNCTION fn_ty_wf_legacy_contract_lock()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE key bigint;
BEGIN
 IF TG_TABLE_NAME='ty_outsource_contract'THEN
  IF TG_OP='DELETE'AND EXISTS(SELECT 1 FROM public.ty_wf_contract_control WHERE contract_id=OLD.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已登记服务合同须保留原件和履历';END IF;
  IF TG_OP='UPDATE'AND EXISTS(SELECT 1 FROM public.ty_wf_contract_control WHERE contract_id=OLD.id)AND(to_jsonb(NEW)-ARRAY['status','updated_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','updated_at'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='受控合同原始主体、期间、公司和条款不可由旧表改写';END IF;
 ELSE
  key:=CASE WHEN TG_OP='DELETE'THEN OLD.contract_id ELSE NEW.contract_id END;
  IF EXISTS(SELECT 1 FROM public.ty_wf_contract_control WHERE contract_id=key)OR TG_OP='UPDATE'AND EXISTS(SELECT 1 FROM public.ty_wf_contract_control WHERE contract_id=OLD.contract_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已登记服务合同的适用公司保留，范围变更须另建受控合同';END IF;
 END IF;RETURN CASE WHEN TG_OP='DELETE'THEN OLD ELSE NEW END;
END;$$;
CREATE TRIGGER ty_wf_contract_parent_lock BEFORE UPDATE OR DELETE ON ty_outsource_contract FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_legacy_contract_lock();
CREATE TRIGGER ty_wf_contract_scope_lock BEFORE INSERT OR UPDATE OR DELETE ON ty_outsource_contract_company FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_legacy_contract_lock();

-- BEGIN WORKFORCE APPROVAL FRAGMENT
-- This fragment is appended into private226 before freeze. Do not migrate it independently.
CREATE TABLE ty_wf_approval_execution(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),subject_type text NOT NULL,subject_id bigint NOT NULL,
 instance_id bigint NOT NULL UNIQUE REFERENCES ty_workflow_instance(id),source_hash text NOT NULL,original_created_by bigint NOT NULL REFERENCES sys_account(id),submitted_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint NOT NULL REFERENCES sys_account(id),executed_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(subject_type,subject_id)
);
CREATE TRIGGER ty_wf_execution_immutable BEFORE UPDATE OR DELETE ON ty_wf_approval_execution FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_append_only();
CREATE FUNCTION fn_ty_wf_execution_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE i public.ty_workflow_instance;
BEGIN SELECT*INTO i FROM public.ty_workflow_instance WHERE id=NEW.instance_id;
 IF i.id IS NULL OR i.status<>'approved'OR i.business_state NOT IN('pending','applied')OR i.subject_type<>NEW.subject_type OR i.subject_id<>NEW.subject_id OR i.group_id<>NEW.group_id OR i.company_id IS DISTINCT FROM NEW.company_id OR i.source_hash<>NEW.source_hash OR i.last_approver_id<>NEW.approved_by OR i.applicant_id<>NEW.submitted_by OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.submitted_by)OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.original_created_by)OR public.fn_ty_hr_actor_is_person(NEW.approved_by,i.group_id,i.person_id)OR NOT EXISTS(SELECT 1 FROM public.ty_workflow_task WHERE instance_id=i.id AND approver_id=NEW.approved_by AND status='approved'AND acted_at IS NOT NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='业务办理必须保留确切来源、真实独立审批节点与实际办理人';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_wf_execution_guard BEFORE INSERT ON ty_wf_approval_execution FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_execution_guard();

-- UTC is local to this function. DATE stays a date; timestamp facts have one representation on every host.
CREATE FUNCTION fn_ty_wf_approval_fingerprint(p_type text,p_id bigint)RETURNS text LANGUAGE plpgsql STABLE SET search_path='' SET timezone='UTC'AS $$
DECLARE table_name text;record_json jsonb;deps jsonb:='{}';supplier_key bigint;contract_key bigint;employment_key bigint;root_key bigint;version_key bigint;
BEGIN
 table_name:=CASE p_type WHEN'workforce_profile'THEN'ty_wf_vendor_profile'WHEN'workforce_price'THEN'ty_wf_price'WHEN'workforce_contract'THEN'ty_wf_contract_control'WHEN'workforce_order'THEN'ty_wf_order'WHEN'workforce_engagement'THEN'ty_wf_engagement_review'WHEN'workforce_acceptance'THEN'ty_wf_acceptance_version'WHEN'workforce_bill'THEN'ty_wf_bill_version'WHEN'workforce_opening'THEN'ty_wf_opening'WHEN'workforce_bank_receipt'THEN'ty_wf_bank_receipt'WHEN'workforce_advance'THEN'ty_wf_advance'WHEN'workforce_payment'THEN'ty_wf_payment'WHEN'workforce_mandate'THEN'ty_wf_mandate'WHEN'workforce_instruction'THEN'ty_wf_personal_instruction'WHEN'workforce_personal_receipt'THEN'ty_wf_personal_receipt'END;
 IF table_name IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='未定义的用工审批类型';END IF;
 EXECUTE format('SELECT to_jsonb(x)FROM public.%I x WHERE %I=$1',table_name,CASE WHEN p_type='workforce_contract'THEN'contract_id'ELSE'id'END)INTO record_json USING p_id;IF record_json IS NULL THEN RETURN NULL;END IF;
 contract_key:=(record_json->>'contract_id')::bigint;supplier_key:=(record_json->>'supplier_id')::bigint;employment_key:=(record_json->>'employment_id')::bigint;root_key:=(record_json->>'root_id')::bigint;
 IF p_type='workforce_engagement'THEN SELECT jsonb_build_object('engagement',to_jsonb(e),'employment',to_jsonb(em),'order',to_jsonb(o),'qualification',to_jsonb(p)),e.contract_id,e.employment_id INTO deps,contract_key,employment_key FROM public.ty_outsource_engagement e JOIN public.ty_employment em ON em.id=e.employment_id LEFT JOIN public.ty_wf_order o ON o.id=(record_json->>'order_id')::bigint LEFT JOIN public.ty_wf_vendor_profile p ON p.id=(record_json->>'qualification_profile_id')::bigint WHERE e.id=(record_json->>'engagement_id')::bigint;
 ELSIF p_type='workforce_acceptance'THEN SELECT jsonb_build_object('root',to_jsonb(r),'allocations',(SELECT jsonb_agg(to_jsonb(a)ORDER BY a.id)FROM public.ty_wf_acceptance_allocation a WHERE a.acceptance_version_id=p_id),'time_root',to_jsonb(tr),'time_report',to_jsonb(tv)),r.employment_id INTO deps,employment_key FROM public.ty_wf_acceptance_root r LEFT JOIN public.ty_time_report_root tr ON tr.id=(record_json->>'source_root_id')::bigint LEFT JOIN public.ty_time_report_version tv ON tv.id=tr.current_report_id WHERE r.id=root_key;
 ELSIF p_type='workforce_bill'THEN SELECT jsonb_build_object('root',to_jsonb(r),'lines',(SELECT jsonb_agg(to_jsonb(l)ORDER BY l.id)FROM public.ty_wf_bill_line l WHERE l.version_id=p_id),'acceptance_roots',(SELECT jsonb_agg(to_jsonb(a)ORDER BY a.id)FROM public.ty_wf_acceptance_root a WHERE a.id IN(SELECT v.root_id FROM public.ty_wf_acceptance_version v JOIN public.ty_wf_bill_line l ON l.acceptance_version_id=v.id WHERE l.version_id=p_id)),'instructions',(SELECT jsonb_agg(to_jsonb(i)ORDER BY i.id)FROM public.ty_wf_personal_instruction i WHERE i.id IN(SELECT l.personal_instruction_id FROM public.ty_wf_bill_line l WHERE l.version_id=p_id))),r.contract_id INTO deps,contract_key FROM public.ty_wf_bill_root r WHERE r.id=root_key;
 ELSIF p_type='workforce_opening'THEN SELECT jsonb_build_object('root',to_jsonb(r),'legacy_bill',to_jsonb(b)),r.contract_id INTO deps,contract_key FROM public.ty_wf_bill_root r LEFT JOIN public.ty_outsource_bill b ON b.id=r.legacy_bill_id WHERE r.id=root_key;
 ELSIF p_type='workforce_price'THEN deps:=jsonb_build_object('tiers',(SELECT jsonb_agg(to_jsonb(x)ORDER BY x.lower_quantity)FROM public.ty_wf_price_tier x WHERE price_id=p_id));
 ELSIF p_type='workforce_payment'THEN SELECT jsonb_build_object('payable',to_jsonb(a),'allocations',(SELECT jsonb_agg(to_jsonb(x)ORDER BY x.id)FROM public.ty_wf_payment_allocation x WHERE payment_id=p_id),'bank',to_jsonb(b)),r.contract_id INTO deps,contract_key FROM public.ty_wf_payable a JOIN public.ty_wf_bill_root r ON r.id=a.root_id LEFT JOIN public.ty_wf_vendor_profile b ON b.id=(record_json->>'bank_profile_id')::bigint WHERE a.id=(record_json->>'payable_id')::bigint;
 ELSIF p_type='workforce_advance'THEN deps:=jsonb_build_object('bank',(SELECT to_jsonb(x)FROM public.ty_wf_bank_receipt x WHERE id=(record_json->>'bank_receipt_id')::bigint));
 ELSIF p_type='workforce_instruction'THEN deps:=jsonb_build_object('mandate',(SELECT to_jsonb(x)FROM public.ty_wf_mandate x WHERE id=(record_json->>'mandate_id')::bigint),'confirmed_wages',(SELECT jsonb_agg(jsonb_build_object('row',to_jsonb(r),'batch',to_jsonb(b),'relationship',to_jsonb(rc))ORDER BY r.id)FROM public.ty_pay_row r JOIN public.ty_pay_batch b ON b.id=r.batch_id JOIN public.ty_pay_config rc ON rc.id=r.relationship_config_id WHERE r.employment_id=employment_key AND b.status='confirmed'AND b.period=(record_json->>'period')::date));
 ELSIF p_type='workforce_personal_receipt'THEN SELECT jsonb_build_object('instruction',to_jsonb(i),'original_receipt',to_jsonb(o),'bank',to_jsonb(b)),i.contract_id,i.employment_id,i.supplier_id INTO deps,contract_key,employment_key,supplier_key FROM public.ty_wf_personal_instruction i LEFT JOIN public.ty_wf_personal_receipt o ON o.id=(record_json->>'original_receipt_id')::bigint LEFT JOIN public.ty_wf_bank_receipt b ON b.id=(record_json->>'bank_receipt_id')::bigint WHERE i.id=(record_json->>'instruction_id')::bigint;
 END IF;
 IF p_type='workforce_engagement'THEN deps:=deps||jsonb_build_object('legal_start',(SELECT to_jsonb(v)FROM public.fn_ty_hr_verified_legal_subject(employment_key,(record_json->>'valid_from')::date)v),'legal_end',(SELECT to_jsonb(v)FROM public.fn_ty_hr_verified_legal_subject(employment_key,(record_json->>'valid_to')::date-1)v));END IF;
 IF employment_key IS NOT NULL THEN deps:=deps||jsonb_build_object('employment',(SELECT to_jsonb(x)FROM public.ty_employment x WHERE x.id=employment_key));END IF;
 IF contract_key IS NOT NULL THEN SELECT supplier_id INTO supplier_key FROM public.ty_outsource_contract WHERE id=contract_key;deps:=deps||jsonb_build_object('contract',(SELECT to_jsonb(x)FROM public.ty_outsource_contract x WHERE id=contract_key),'contract_companies',(SELECT jsonb_agg(company_id ORDER BY company_id)FROM public.ty_outsource_contract_company WHERE contract_id=contract_key));END IF;
 IF supplier_key IS NOT NULL THEN deps:=deps||jsonb_build_object('supplier',(SELECT to_jsonb(x)FROM public.ty_outsource_supplier x WHERE id=supplier_key));IF p_type='workforce_profile'THEN deps:=deps||jsonb_build_object('affected_companies',(SELECT jsonb_agg(company_id ORDER BY company_id)FROM(SELECT DISTINCT cc.company_id FROM public.ty_outsource_contract c JOIN public.ty_outsource_contract_company cc ON cc.contract_id=c.id WHERE c.supplier_id=supplier_key)x));END IF;END IF;
 RETURN md5(jsonb_build_object('type',p_type,'record',record_json,'dependencies',deps)::text);
END;$$;
-- END WORKFORCE APPROVAL FRAGMENT
